  };

  const handleDownloadQR = async () => {
    if (!shareLink) return;

    const qrUrl = generateQRCodeUrl(shareLink.url, 400);
    const response = await fetch(qrUrl);
    const blob = await response.blob();
    const url = URL.createObjectURL(blob);

