import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { greenRoomService } from '../services/greenRoomService';
import type {
  BookProject,
  Character,
  CharacterPersona,
  GreenRoomMessage,
  GreenRoomSession,
} from '../types';
import { Button } from '@components/ui/button';
import { Input } from '@components/ui/input';

interface GreenRoomProps {
  isOpen: boolean;
  onClose: () => void;
  project: BookProject;
  character: Character;
  onPersonaUpdate?: (persona: CharacterPersona) => void;
  userId?: string;
}

export const GreenRoom: React.FC<GreenRoomProps> = ({
  isOpen,
  onClose,
  project,
  character,
  onPersonaUpdate,
  userId,
}) => {
  // State
  const [persona, setPersona] = useState<CharacterPersona | null>(null);
  const [session, setSession] = useState<GreenRoomSession | null>(null);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(true);
  const [showFacts, setShowFacts] = useState(true);
  const [showHistory, setShowHistory] = useState(false);
  const [previousSessions, setPreviousSessions] = useState<GreenRoomSession[]>([]);
  const [suggestedQuestions, setSuggestedQuestions] = useState<string[]>([]);
  const [ambientMode, setAmbientMode] = useState(true);
  const [newFactHighlight, setNewFactHighlight] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Initialize persona and session
  useEffect(() => {
    if (isOpen && character) {
      const initialPersona = greenRoomService.initializePersona(character, project);
      setPersona(initialPersona);

      const newSession = greenRoomService.createSession(project.id, initialPersona);
      setSession(newSession);

      setSuggestedQuestions(greenRoomService.getSuggestedQuestions(initialPersona));

      // Load previous sessions if we have a user
      if (userId) {
        greenRoomService.loadSessions(userId, character.id || '').then(setPreviousSessions);
      }
    }
  }, [isOpen, character, project, userId]);

  // Scroll to bottom on new messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [session?.messages]);

  // Handle sending a message
  const handleSend = useCallback(async () => {
    if (!inputValue.trim() || !session || !persona || isTyping) return;

    const message = inputValue.trim();
    setInputValue('');
    setIsTyping(true);

    // Optimistically add author message
    const authorMsg: GreenRoomMessage = {
      id: `temp-${Date.now()}`,
      role: 'author',
      content: message,
      timestamp: Date.now(),
    };
    setSession((prev) =>
      prev
        ? {
            ...prev,
            messages: [...prev.messages, authorMsg],
          }
        : null
    );

    try {
      const { updatedSession, updatedPersona, newMessage } = await greenRoomService.sendMessage(
        session,
        persona,
        message,
        {
          title: project.title,
          synopsis: project.synopsis,
          tone: project.tone,
        }
      );

      console.log('Γ£à Green Room response received:', newMessage);

      setSession(updatedSession);
      setPersona(updatedPersona);

      // Highlight new facts
      if (newMessage.extractedFacts && newMessage.extractedFacts.length > 0) {
        setNewFactHighlight(newMessage.extractedFacts[0].id);
        setTimeout(() => setNewFactHighlight(null), 3000);
      }

      // Update suggested questions
      setSuggestedQuestions(greenRoomService.getSuggestedQuestions(updatedPersona));

      // Notify parent of persona update
      if (onPersonaUpdate) {
        onPersonaUpdate(updatedPersona);
      }

      // Save session
      if (userId) {
        greenRoomService.saveSession(userId, updatedSession);
      }
    } catch (error) {
      console.error('Γ¥î Error in Green Room:', error);

      // Add error message to session
      const errorMsg: GreenRoomMessage = {
        id: `error-${Date.now()}`,
        role: 'character',
        content: `*${persona?.name || 'The character'} seems distracted...* \n\nI'm having trouble responding right now. Could you try asking again?`,
        timestamp: Date.now(),
      };

      setSession((prev) =>
        prev
          ? {
              ...prev,
              messages: [...prev.messages, errorMsg],
            }
          : null
      );
    } finally {
      setIsTyping(false);
    }
  }, [inputValue, session, persona, isTyping, project, onPersonaUpdate, userId]);

  // Handle suggested question click
  const handleSuggestionClick = (question: string) => {
    setInputValue(question);
    inputRef.current?.focus();
  };

  // Format timestamp
  const formatTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[100] flex items-center justify-center"
      >
        {/* Backdrop with ambient effect */}
        <div
          className={`absolute inset-0 transition-all duration-1000 ${
            ambientMode
              ? 'bg-gradient-to-br from-emerald-950 via-slate-950 to-purple-950'
              : 'bg-slate-950'
          }`}
          onClick={onClose}
        >
          {/* Ambient particles */}
          {ambientMode && (
            <div className="absolute inset-0 overflow-hidden pointer-events-none">
              {[...Array(20)].map((_, i) => (
                <motion.div
                  key={i}
                  className="absolute w-1 h-1 rounded-full bg-emerald-400/30"
                  initial={{
                    x: Math.random() * window.innerWidth,
                    y: Math.random() * window.innerHeight,
                    scale: 0,
                  }}
                  animate={{
                    y: [null, Math.random() * -200],
                    scale: [0, 1, 0],
                    opacity: [0, 0.6, 0],
                  }}
                  transition={{
                    duration: 4 + Math.random() * 4,
                    repeat: Number.POSITIVE_INFINITY,
                    delay: Math.random() * 2,
                  }}
                />
              ))}
            </div>
          )}
        </div>

        {/* Main Container */}
        <motion.div
          initial={{ scale: 0.9, y: 20 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.9, y: 20 }}
          className="relative w-full max-w-6xl h-[90vh] mx-4 bg-slate-900/95 backdrop-blur-xl rounded-3xl border border-emerald-500/20 overflow-hidden flex flex-col"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Header */}
          <div className="relative px-6 py-4 border-b border-white/10 bg-gradient-to-r from-emerald-900/30 via-transparent to-purple-900/30">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                {/* Character Avatar */}
                <div className="relative">
                  <div className="flex items-center justify-center overflow-hidden border-2 w-14 h-14 rounded-2xl bg-gradient-to-br from-emerald-500 to-teal-600 border-emerald-400/50">
                    {persona?.avatarUrl ? (
                      <img
                        src={persona.avatarUrl}
                        alt={persona.name}
                        className="object-cover w-full h-full"
                      />
                    ) : (
                      <User className="text-white w-7 h-7" />
                    )}
                  </div>
                  <div className="absolute w-4 h-4 border-2 rounded-full -bottom-1 -right-1 bg-emerald-500 border-slate-900 animate-pulse" />
                </div>

                <div>
                  <h2 className="flex items-center gap-2 text-xl font-bold text-white">
                    <span className="text-emerald-400">The Green Room</span>
                    <span className="text-white/50">with</span>
                    <span className="text-white">{persona?.name || character.name}</span>
                  </h2>
                  <p className="flex items-center gap-2 text-sm text-emerald-300/60">
                    <Sparkles className="w-3 h-3" />
                    Character Interview Session
                    {session && (
                      <span className="text-emerald-400/50">
                        ΓÇó {session.totalFactsExtracted} facts discovered
                      </span>
                    )}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                {/* Ambient Toggle */}
                <Button
                  onClick={() => setAmbientMode(!ambientMode)}
                  variant="ghost"
                  size="icon"
                  className={`${
                    ambientMode
                      ? 'bg-emerald-500/20 text-emerald-400'
                      : 'text-white/40 hover:text-white/60'
                  }`}
                  title="Toggle ambient mode"
                >
                  <Sparkles className="w-5 h-5" />
                </Button>

                {/* History Toggle */}
                <Button
                  onClick={() => setShowHistory(!showHistory)}
                  variant="ghost"
                  size="icon"
                  className={`${
                    showHistory
                      ? 'bg-purple-500/20 text-purple-400'
                      : 'text-white/40 hover:text-white/60'
                  }`}
                  title="View session history"
                >
                  <History className="w-5 h-5" />
                </Button>

                {/* Close */}
                <Button
                  onClick={onClose}
                  variant="ghost"
                  size="icon"
                  className="text-white/40 hover:text-white hover:bg-white/10"
                >
                  <X className="w-5 h-5" />
                </Button>
              </div>
            </div>
          </div>

          {/* Main Content Area */}
          <div className="flex flex-1 overflow-hidden">
            {/* Chat Panel */}
            <div className="flex flex-col flex-1 min-w-0">
              {/* Messages */}
              <div className="flex-1 p-6 space-y-4 overflow-y-auto">
                {session?.messages.map((msg, index) => (
                  <motion.div
                    key={msg.id}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: index * 0.05 }}
                    className={`flex ${msg.role === 'author' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div className={`max-w-[80%] ${msg.role === 'author' ? 'order-2' : 'order-1'}`}>
                      {/* Message Bubble */}
                      <div
                        className={`rounded-2xl px-4 py-3 ${
                          msg.role === 'author'
                            ? 'bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-br-md'
                            : 'bg-gradient-to-r from-emerald-800/50 to-teal-800/50 text-white border border-emerald-500/20 rounded-bl-md'
                        }`}
                      >
                        <p className="text-sm leading-relaxed whitespace-pre-wrap">{msg.content}</p>
                      </div>

                      {/* Extracted Facts */}
                      {msg.extractedFacts && msg.extractedFacts.length > 0 && (
                        <motion.div
                          initial={{ opacity: 0, height: 0 }}
                          animate={{ opacity: 1, height: 'auto' }}
                          className="flex flex-wrap gap-1 mt-2"
                        >
                          {msg.extractedFacts.map((fact) => (
                            <motion.span
                              key={fact.id}
                              initial={{ scale: 0 }}
                              animate={{ scale: 1 }}
                              className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs ${
                                newFactHighlight === fact.id
                                  ? 'bg-yellow-500/30 text-yellow-300 border border-yellow-500/50'
                                  : 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/30'
                              }`}
                            >
                              <Zap className="w-3 h-3" />
                              {fact.key.replace(/_/g, ' ')}: {fact.value}
                            </motion.span>
                          ))}
                        </motion.div>
                      )}

                      {/* Timestamp */}
                      <p
                        className={`text-xs text-white/30 mt-1 ${msg.role === 'author' ? 'text-right' : 'text-left'}`}
                      >
                        {formatTime(msg.timestamp)}
                      </p>
                    </div>
                  </motion.div>
                ))}

                {/* Typing Indicator */}
                {isTyping && (
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="flex justify-start"
                  >
                    <div className="px-4 py-3 border bg-emerald-800/30 border-emerald-500/20 rounded-2xl rounded-bl-md">
                      <div className="flex items-center gap-2">
                        <div className="flex gap-1">
                          <span
                            className="w-2 h-2 rounded-full bg-emerald-400 animate-bounce"
                            style={{ animationDelay: '0ms' }}
                          />
                          <span
                            className="w-2 h-2 rounded-full bg-emerald-400 animate-bounce"
                            style={{ animationDelay: '150ms' }}
                          />
                          <span
                            className="w-2 h-2 rounded-full bg-emerald-400 animate-bounce"
                            style={{ animationDelay: '300ms' }}
                          />
                        </div>
                        <span className="text-xs italic text-emerald-400/60">
                          {persona?.name} is thinking...
                        </span>
                      </div>
                    </div>
                  </motion.div>
                )}

                <div ref={messagesEndRef} />
              </div>

              {/* Suggested Questions */}
              <AnimatePresence>
                {showSuggestions && suggestedQuestions.length > 0 && !isTyping && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    exit={{ opacity: 0, height: 0 }}
                    className="px-6 pb-2"
                  >
                    <div className="flex items-center gap-2 mb-2">
                      <Lightbulb className="w-4 h-4 text-yellow-400" />
                      <span className="text-xs font-medium text-yellow-400/80">
                        Suggested Questions
                      </span>
                      <Button
                        onClick={() => setShowSuggestions(false)}
                        variant="ghost"
                        size="icon"
                        className="ml-auto text-white/30 hover:text-white/50"
                      >
                        <ChevronUp className="w-4 h-4" />
                      </Button>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {suggestedQuestions.slice(0, 3).map((q, i) => (
                        <Button
                          key={i}
                          onClick={() => handleSuggestionClick(q)}
                          variant="outline"
                          size="sm"
                          className="bg-white/5 hover:bg-white/10 border border-white/10 hover:border-yellow-500/30 rounded-full text-white/70 hover:text-white"
                        >
                          {q}
                        </Button>
                      ))}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Input Area */}
              <div className="p-4 border-t border-white/10 bg-slate-900/50">
                <div className="flex items-center gap-3">
                  <div className="relative flex-1">
                    <Input
                      ref={inputRef}
                      type="text"
                      value={inputValue}
                      onChange={(e) => setInputValue(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && handleSend()}
                      placeholder={`Ask ${persona?.name || 'the character'} anything...`}
                      className="py-3 text-white bg-white/5 border-white/10 placeholder-white/30 focus:border-emerald-500/50 focus:ring-2 focus:ring-emerald-500/20"
                      disabled={isTyping}
                    />
                  </div>

                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={handleSend}
                    disabled={!inputValue.trim() || isTyping}
                    className="p-3 text-white transition-all bg-gradient-to-r from-emerald-500 to-teal-500 rounded-xl border-2 border-white/20 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <Send className="w-5 h-5" />
                  </motion.button>
                </div>
              </div>
            </div>

            {/* Right Sidebar - Facts & Info */}
            <div className="flex-col hidden border-l lg:flex w-80 border-white/10 bg-slate-900/30">
              {/* Character Card */}
              <div className="p-4 border-b border-white/10">
                <div className="p-4 border bg-gradient-to-br from-emerald-900/30 to-teal-900/30 rounded-xl border-emerald-500/20">
                  <div className="flex items-center gap-3 mb-3">
                    <div className="flex items-center justify-center w-12 h-12 overflow-hidden rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600">
                      {persona?.avatarUrl ? (
                        <img
                          src={persona.avatarUrl}
                          alt={persona.name}
                          className="object-cover w-full h-full"
                        />
                      ) : (
                        <User className="w-6 h-6 text-white" />
                      )}
                    </div>
                    <div>
                      <h3 className="font-bold text-white">{persona?.name}</h3>
                      <p className="text-xs capitalize text-emerald-400/60">
                        {persona?.role || 'Character'}
                      </p>
                    </div>
                  </div>

                  {persona?.voiceStyle && (
                    <p className="mb-2 text-xs italic text-white/50">"{persona.voiceStyle}"</p>
                  )}

                  {/* Quick Stats */}
                  <div className="flex gap-2 mt-3">
                    <div className="flex-1 p-2 text-center rounded-lg bg-black/20">
                      <p className="text-lg font-bold text-emerald-400">
                        {persona?.extractedFacts.length || 0}
                      </p>
                      <p className="text-xs text-white/40">Facts</p>
                    </div>
                    <div className="flex-1 p-2 text-center rounded-lg bg-black/20">
                      <p className="text-lg font-bold text-purple-400">
                        {session?.messages.length || 0}
                      </p>
                      <p className="text-xs text-white/40">Messages</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Discovered Facts */}
              <div className="flex-1 p-4 overflow-y-auto">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="flex items-center gap-2 text-sm font-medium text-white/80">
                    <Star className="w-4 h-4 text-yellow-400" />
                    Discovered Facts
                  </h4>
                  <Button
                    onClick={() => setShowFacts(!showFacts)}
                    variant="ghost"
                    size="icon"
                    className="text-white/30 hover:text-white/50"
                  >
                    {showFacts ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </Button>
                </div>

                {showFacts && persona?.extractedFacts && persona.extractedFacts.length > 0 ? (
                  <div className="space-y-2">
                    {persona.extractedFacts.map((fact, i) => (
                      <motion.div
                        key={fact.id}
                        initial={{ opacity: 0, x: 20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: i * 0.05 }}
                        className={`p-3 rounded-lg border transition-all ${
                          newFactHighlight === fact.id
                            ? 'bg-yellow-500/20 border-yellow-500/50'
                            : 'bg-white/5 border-white/10 hover:border-emerald-500/30'
                        }`}
                      >
                        <div className="flex items-start gap-2">
                          <Tag className="w-3 h-3 text-emerald-400 mt-0.5 shrink-0" />
                          <div>
                            <p className="text-xs font-medium capitalize text-emerald-400/80">
                              {fact.key.replace(/_/g, ' ')}
                            </p>
                            <p className="text-sm text-white/80">{fact.value}</p>
                          </div>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                ) : showFacts ? (
                  <div className="py-8 text-center">
                    <Sparkles className="w-8 h-8 mx-auto mb-2 text-white/20" />
                    <p className="text-sm text-white/40">
                      Ask questions to discover facts about {persona?.name}
                    </p>
                  </div>
                ) : null}
              </div>

              {/* Interview Tips */}
              <div className="p-4 border-t border-white/10">
                <div className="p-3 border rounded-lg bg-purple-900/20 border-purple-500/20">
                  <h5 className="flex items-center gap-1 mb-1 text-xs font-medium text-purple-300">
                    <Lightbulb className="w-3 h-3" />
                    Interview Tip
                  </h5>
                  <p className="text-xs text-white/50">
                    Ask about emotions and memories. Characters reveal the most when talking about
                    their past.
                  </p>
                </div>
              </div>
            </div>

            {/* Session History Sidebar */}
            <AnimatePresence>
              {showHistory && (
                <motion.div
                  initial={{ width: 0, opacity: 0 }}
                  animate={{ width: 280, opacity: 1 }}
                  exit={{ width: 0, opacity: 0 }}
                  className="overflow-hidden border-l border-white/10 bg-slate-900/50"
                >
                  <div className="p-4">
                    <h4 className="flex items-center gap-2 mb-3 text-sm font-medium text-white/80">
                      <History className="w-4 h-4 text-purple-400" />
                      Previous Sessions
                    </h4>

                    {previousSessions.length > 0 ? (
                      <div className="space-y-2">
                        {previousSessions.map((s) => (
                          <Button
                            key={s.id}
                            onClick={() => {
                              setSession(s);
                              setShowHistory(false);
                            }}
                            variant="ghost"
                            className="w-full p-3 text-left bg-white/5 hover:bg-white/10 h-auto flex-col items-start"
                          >
                            <div className="flex items-center gap-2 mb-1">
                              <Clock className="w-3 h-3 text-white/40" />
                              <span className="text-xs text-white/40">
                                {new Date(s.startedAt).toLocaleDateString()}
                              </span>
                            </div>
                            <p className="text-sm text-white/70">{s.messages.length} messages</p>
                            <p className="text-xs text-emerald-400/60">
                              {s.totalFactsExtracted} facts discovered
                            </p>
                          </Button>
                        ))}
                      </div>
                    ) : (
                      <p className="py-4 text-sm text-center text-white/40">No previous sessions</p>
                    )}

                    {/* New Session Button */}
                    <Button
                      onClick={() => {
                        if (persona) {
                          setSession(greenRoomService.createSession(project.id, persona));
                        }
                        setShowHistory(false);
                      }}
                      variant="outline"
                      className="w-full mt-4 bg-emerald-500/20 hover:bg-emerald-500/30 border-emerald-500/30 text-emerald-400"
                    >
                      <Plus className="w-4 h-4" />
                      New Session
                    </Button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default GreenRoom;

import { Download, X } from 'lucide-react';
import type React from 'react';
import { useEffect, useState } from 'react';
import { Button } from './ui/button';

const InstallPWA: React.FC = () => {
  const [supportsPWA, setSupportsPWA] = useState(false);
  const [promptInstall, setPromptInstall] = useState<any>(null);

  useEffect(() => {
    const handler = (e: any) => {
      e.preventDefault();
      setSupportsPWA(true);
      setPromptInstall(e);
    };
    window.addEventListener('beforeinstallprompt', handler);

    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const onClick = (evt: React.MouseEvent) => {
    evt.preventDefault();
    if (!promptInstall) {
      return;
    }
    promptInstall.prompt();
  };

  if (!supportsPWA) {
    return null;
  }

  return (
    <div className="fixed bottom-20 left-4 right-4 md:bottom-4 md:left-auto md:right-4 z-[100] animate-fadeIn">
      <div className="bg-white/90 backdrop-blur-md border border-gray-200 rounded-2xl p-4 flex items-center justify-between gap-4 max-w-sm ml-auto">
        <div className="flex items-center gap-3">
          <div className="bg-coral-burst/10 p-2 rounded-xl">
            <Download className="w-6 h-6 text-coral-burst" />
          </div>
          <div>
            <h3 className="font-bold text-charcoal-soft text-sm">Install App</h3>
            <p className="text-xs text-gray-500">Add to home screen for better experience</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button
            onClick={() => setSupportsPWA(false)}
            variant="ghost"
            size="icon"
            className="p-2 hover:bg-gray-100 rounded-full text-gray-400"
          >
            <X size={18} />
          </Button>
          <Button
            onClick={onClick}
            variant="default"
            size="sm"
            className="bg-coral-burst text-white px-4 py-2 text-xs hover:bg-coral-hover border-2 border-white/20"
          >
            Install
          </Button>
        </div>
      </div>
    </div>
  );
};

export default InstallPWA;

/**
 * Interactive Character Tutor
 * Visual character that speaks and animates while tutoring
 * Like Talking Tom but for educational content
 */

import { AnimatePresence, motion } from 'framer-motion';
import { Pause, Play, RotateCcw, Volume2, VolumeX } from 'lucide-react';
import type React from 'react';
import { useEffect, useRef, useState } from 'react';
import { characterVoiceTutoringService } from '../services/characterVoiceTutoringService';
import type { Character } from '../types';

interface InteractiveCharacterTutorProps {
  character: Character;
  learningContent?: {
    topic: string;
    mentorDialogue: string;
    quiz?: {
      question: string;
      options: string[];
      correctAnswer: string;
      explanation?: string;
    };
  };
  onQuizComplete?: (correct: boolean) => void;
  autoStart?: boolean;
}

export const InteractiveCharacterTutor: React.FC<InteractiveCharacterTutorProps> = ({
  character,
  learningContent,
  onQuizComplete,
  autoStart = false,
}) => {
  const [isActive, setIsActive] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [expression, setExpression] = useState<string>('neutral');
  const [showQuiz, setShowQuiz] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<string | null>(null);
  const [quizFeedback, setQuizFeedback] = useState<{ show: boolean; correct: boolean } | null>(
    null
  );
  const [isPaused, setIsPaused] = useState(false);
  const sessionStarted = useRef(false);

  // Start session on mount
  useEffect(() => {
    if (autoStart && !sessionStarted.current && learningContent) {
      startTutoring();
      sessionStarted.current = true;
    }

    return () => {
      characterVoiceTutoringService.stop();
    };
  }, [autoStart, learningContent]);

  const startTutoring = async () => {
    setIsActive(true);

    // Start session with expression callback
    characterVoiceTutoringService.startSession(character, (expr) => {
      setExpression(expr);
    });

    // Set speech state callback
    characterVoiceTutoringService.onSpeechEnd(() => {
      setIsSpeaking(false);
    });

    setIsSpeaking(true);

    // Wait for greeting
    await new Promise((resolve) => setTimeout(resolve, 2000));

    if (learningContent) {
      // Speak the learning content
      setIsSpeaking(true);
      await characterVoiceTutoringService.speakLearningContent(
        learningContent.mentorDialogue,
        learningContent.topic
      );
      setIsSpeaking(false);

      // Show quiz if available
      if (learningContent.quiz) {
        setTimeout(() => {
          askQuiz();
        }, 500);
      }
    }
  };

  const askQuiz = async () => {
    if (!learningContent?.quiz) return;

    setShowQuiz(true);
    setIsSpeaking(true);

    await characterVoiceTutoringService.speakQuizQuestion(learningContent.quiz.question);

    setIsSpeaking(false);
  };

  const handleAnswerSelect = async (answer: string) => {
    if (!learningContent?.quiz) return;

    setSelectedAnswer(answer);
    const isCorrect = answer === learningContent.quiz.correctAnswer;

    setQuizFeedback({ show: true, correct: isCorrect });
    setIsSpeaking(true);

    await characterVoiceTutoringService.giveQuizFeedback(
      isCorrect,
      learningContent.quiz.explanation
    );

    setIsSpeaking(false);

    if (onQuizComplete) {
      onQuizComplete(isCorrect);
    }

    // Hide quiz after feedback
    setTimeout(() => {
      setShowQuiz(false);
      setQuizFeedback(null);
      setSelectedAnswer(null);
    }, 3000);
  };

  const togglePause = () => {
    if (isPaused) {
      characterVoiceTutoringService.resume();
    } else {
      characterVoiceTutoringService.pause();
    }
    setIsPaused(!isPaused);
  };

  const stopTutoring = () => {
    characterVoiceTutoringService.stop();
    setIsActive(false);
    setIsSpeaking(false);
    setShowQuiz(false);
    setExpression('neutral');
  };

  const restartTutoring = () => {
    stopTutoring();
    setTimeout(() => startTutoring(), 300);
  };

  // Character expression classes
  const getExpressionClasses = () => {
    switch (expression) {
      case 'happy':
        return 'scale-110 rotate-2';
      case 'thinking':
        return 'scale-105 -rotate-1';
      case 'excited':
        return 'scale-125 animate-bounce';
      case 'encouraging':
        return 'scale-105';
      default:
        return 'scale-100';
    }
  };

  // Speaking animation (mouth movement)
  const getSpeakingAnimation = () => {
    if (isSpeaking) {
      return {
        scale: [1, 1.05, 1],
      };
    }
    return {};
  };

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center p-6 bg-gradient-to-br from-blue-50 to-purple-50 rounded-3xl">
      {/* Character Avatar with Expressions */}
      <motion.div
        className={`relative mb-6 transition-all duration-300 ${getExpressionClasses()}`}
        animate={getSpeakingAnimation()}
      >
        {/* Main Character Image */}
        <div className="relative w-48 h-48 rounded-full overflow-hidden border-8 border-white">
          <img
            src={character.imageUrl}
            alt={character.name}
            className="w-full h-full object-cover"
            onError={(e) => {
              (e.target as HTMLImageElement).src =
                `https://api.dicebear.com/7.x/avataaars/svg?seed=${character.name}`;
            }}
          />

          {/* Speaking indicator - animated mouth overlay */}
          {isSpeaking && (
            <motion.div
              className="absolute bottom-12 left-1/2 -translate-x-1/2 w-16 h-8 bg-white/40 rounded-full backdrop-blur-sm"
              animate={{
                scaleY: [1, 1.3, 0.8, 1.2, 1],
                scaleX: [1, 0.9, 1.1, 0.95, 1],
              }}
              transition={{
                duration: 0.5,
                repeat: Number.POSITIVE_INFINITY,
                ease: 'easeInOut',
              }}
            />
          )}
        </div>

        {/* Expression Emoji Overlay */}
        <AnimatePresence>
          {expression !== 'neutral' && (
            <motion.div
              initial={{ scale: 0, rotate: -180 }}
              animate={{ scale: 1, rotate: 0 }}
              exit={{ scale: 0, rotate: 180 }}
              className="absolute -top-4 -right-4 w-16 h-16 bg-yellow-400 rounded-full flex items-center justify-center text-3xl border-4 border-white"
            >
              {expression === 'happy' && '≡ƒÿè'}
              {expression === 'thinking' && '≡ƒñö'}
              {expression === 'excited' && '≡ƒÄë'}
              {expression === 'encouraging' && '≡ƒÆ¬'}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Speaking Wave Animation */}
        {isSpeaking && (
          <div className="absolute -bottom-2 left-1/2 -translate-x-1/2 flex gap-1">
            {[...Array(5)].map((_, i) => (
              <motion.div
                key={i}
                className="w-1 bg-gradient-to-t from-blue-500 to-purple-500 rounded-full"
                animate={{
                  height: ['8px', '24px', '8px'],
                }}
                transition={{
                  duration: 0.6,
                  repeat: Number.POSITIVE_INFINITY,
                  delay: i * 0.1,
                  ease: 'easeInOut',
                }}
              />
            ))}
          </div>
        )}
      </motion.div>

      {/* Character Name & Topic */}
      <div className="text-center mb-4">
        <h3 className="text-2xl font-heading font-bold text-charcoal-soft mb-1">
          {character.name}
        </h3>
        {learningContent && (
          <p className="text-sm text-blue-600 font-medium">Teaching: {learningContent.topic}</p>
        )}
      </div>

      {/* Quiz Section */}
      <AnimatePresence>
        {showQuiz && learningContent?.quiz && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="w-full max-w-md bg-white rounded-2xl p-6 border-2 border-blue-200"
          >
            <p className="text-lg font-bold text-charcoal-soft mb-4">
              {learningContent.quiz.question}
            </p>

            <div className="space-y-2">
              {learningContent.quiz.options.map((option, index) => (
                <motion.button
                  key={index}
                  onClick={() => !quizFeedback && handleAnswerSelect(option)}
                  disabled={!!quizFeedback}
                  whileHover={{ scale: quizFeedback ? 1 : 1.02 }}
                  whileTap={{ scale: quizFeedback ? 1 : 0.98 }}
                  className={`w-full p-4 rounded-xl text-left transition-all border-2 ${
                    selectedAnswer === option
                      ? quizFeedback?.correct
                        ? 'border-green-500 bg-green-50 text-green-800'
                        : 'border-red-500 bg-red-50 text-red-800'
                      : option === learningContent.quiz?.correctAnswer && quizFeedback
                        ? 'border-green-500 bg-green-50'
                        : 'border-blue-200 bg-white hover:border-blue-400 hover:bg-blue-50'
                  }`}
                >
                  <span className="font-bold mr-2">{String.fromCharCode(65 + index)}.</span>
                  {option}
                </motion.button>
              ))}
            </div>

            {/* Quiz Feedback */}
            {quizFeedback && (
              <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                className={`mt-4 p-4 rounded-xl ${
                  quizFeedback.correct
                    ? 'bg-green-100 border-2 border-green-500'
                    : 'bg-yellow-100 border-2 border-yellow-500'
                }`}
              >
                <p
                  className={`font-bold ${quizFeedback.correct ? 'text-green-800' : 'text-yellow-800'}`}
                >
                  {quizFeedback.correct ? '≡ƒÄë Excellent!' : '≡ƒÆ¬ Good try!'}
                </p>
              </motion.div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Control Buttons */}
      <div className="absolute bottom-4 right-4 flex gap-2">
        {isActive ? (
          <>
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={togglePause}
              className="p-3 bg-blue-500 text-white rounded-full border-2 border-white/20 hover:bg-blue-600 transition-colors"
              title={isPaused ? 'Resume' : 'Pause'}
            >
              {isPaused ? <Play className="w-5 h-5" /> : <Pause className="w-5 h-5" />}
            </motion.button>
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={stopTutoring}
              className="p-3 bg-red-500 text-white rounded-full border-2 border-white/20 hover:bg-red-600 transition-colors"
              title="Stop"
            >
              <VolumeX className="w-5 h-5" />
            </motion.button>
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={restartTutoring}
              className="p-3 bg-purple-500 text-white rounded-full border-2 border-white/20 hover:bg-purple-600 transition-colors"
              title="Restart"
            >
              <RotateCcw className="w-5 h-5" />
            </motion.button>
          </>
        ) : (
          <motion.button
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.9 }}
            onClick={startTutoring}
            className="px-6 py-3 bg-gradient-to-r from-blue-500 to-purple-500 text-white rounded-full border-2 border-white/20 transition-all font-bold flex items-center gap-2"
          >
            <Volume2 className="w-5 h-5" />
            Start Learning
          </motion.button>
        )}
      </div>
    </div>
  );
};

export default InteractiveCharacterTutor;

import {
  AlertCircle,
  BookOpen,
  CheckCircle,
  Download,
  FileText,
  Info,
  Settings,
} from 'lucide-react';
import type React from 'react';
import { useEffect, useState } from 'react';
import { downloadKDP, previewKDPExport } from '../services/export/kdpExportService';
import type { TrimSize } from '../services/export/kdpTypes';
import { getQualityAssessment } from '../services/export/kdpValidation';
import { type BookProject, UserTier } from '../types';
import { Button } from './ui/button';
import { Dialog, DialogContent, DialogFooter } from './ui/dialog';
import { Label } from './ui/input';
import { ScrollArea } from './ui/scroll-area';

interface KDPExportModalProps {
  project: BookProject;
  isOpen: boolean;
  onClose: () => void;
  userTier?: UserTier;
}

const KDPExportModal: React.FC<KDPExportModalProps> = ({
  project,
  isOpen,
  onClose,
  userTier = UserTier.SPARK,
}) => {
  const [trimSize, setTrimSize] = useState<TrimSize>('8.5x8.5');
  const [includeBleed, setIncludeBleed] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);
  const [progressMessage, setProgressMessage] = useState('Preparing export...');
  const [preview, setPreview] = useState<any>(null);
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Load preview when modal opens
  useEffect(() => {
    if (isOpen) {
      loadPreview();
    }
  }, [isOpen, trimSize, includeBleed]);

  const loadPreview = async () => {
    try {
      const previewData = await previewKDPExport(project, {
        trimSize,
        includeBleed,
      });
      setPreview(previewData);
    } catch (error) {
      console.error('Preview failed:', error);
    }
  };

  const handleExport = async () => {
    // Check tier restrictions
    if (userTier === UserTier.SPARK) {
      alert('KDP Export is a premium feature! Upgrade to Creator tier to unlock.');
      return;
    }

    setIsExporting(true);
    setExportProgress(0);
    setProgressMessage('Preparing export...');

    try {
      await downloadKDP(
        project,
        {
          trimSize,
          includeBleed,
          copyrightYear: new Date().getFullYear(),
        },
        (progress, message) => {
          // Real-time progress updates from export service
          setExportProgress(progress);
          setProgressMessage(message);
        }
      );

      // Brief success message before closing
      setProgressMessage('Download complete!');
      setTimeout(() => {
        setIsExporting(false);
        setExportProgress(0);
        onClose();
      }, 1500);
    } catch (error) {
      console.error('Export failed:', error);
      const errorMessage =
        error instanceof Error
          ? error.message
          : 'Export failed. Please check your images and try again.';
      alert(`Export Error: ${errorMessage}`);
      setIsExporting(false);
      setExportProgress(0);
      setProgressMessage('');
    }
  };

  if (!isOpen) return null;

  const qualityAssessment = preview?.quality
    ? getQualityAssessment(preview.quality.overallScore)
    : null;

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
      <DialogContent className="max-w-4xl p-0 overflow-hidden max-h-[90vh] flex flex-col">
        {/* Header */}
        <div className="bg-gradient-to-r from-coral-burst to-gold-sunshine p-6 text-white relative">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center">
              <BookOpen className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-2xl font-heading font-bold">Amazon KDP Export</h2>
              <p className="text-white/90 text-sm">Professional Print-Ready PDF</p>
            </div>
          </div>
        </div>

        {/* Content */}
        <ScrollArea className="flex-1">
          <div className="p-6">
          {/* Quality Dashboard */}
          {preview && preview.quality && (
            <div className="mb-6 p-6 bg-gradient-to-br from-blue-50 to-purple-50 rounded-2xl border border-blue-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-heading font-bold text-charcoal-soft">
                  Quality Assessment
                </h3>
                <div className={`text-3xl font-bold ${qualityAssessment?.color}`}>
                  {preview.quality.overallScore}%
                </div>
              </div>

              {qualityAssessment && (
                <div className={`flex items-center gap-2 mb-4 ${qualityAssessment.color}`}>
                  {qualityAssessment.level === 'excellent' || qualityAssessment.level === 'good' ? (
                    <CheckCircle className="w-5 h-5" />
                  ) : (
                    <AlertCircle className="w-5 h-5" />
                  )}
                  <span className="font-bold">{qualityAssessment.message}</span>
                </div>
              )}

              {/* Quality Metrics */}
              <div className="grid grid-cols-2 gap-3 mb-4">
                <QualityMetric
                  label="Image Resolution"
                  score={preview.quality.imageResolution}
                  icon="≡ƒô╕"
                />
                <QualityMetric
                  label="Color Accuracy"
                  score={preview.quality.colorAccuracy}
                  icon="≡ƒÄ¿"
                />
                <QualityMetric
                  label="Margin Compliance"
                  score={preview.quality.marginCompliance}
                  icon="≡ƒôÉ"
                />
                <QualityMetric
                  label="Font Embedding"
                  score={preview.quality.fontEmbedding}
                  icon="Γ£ì∩╕Å"
                />
              </div>

              {/* File Info */}
              <div className="flex items-center justify-between text-sm text-cocoa-light">
                <span>
                  Estimated File Size: {(preview.estimatedFileSize / 1024 / 1024).toFixed(2)} MB
                </span>
                <span>Pages: {preview.validation.pageCount}</span>
              </div>
            </div>
          )}

          {/* Export Settings */}
          <div className="mb-6">
            <h3 className="text-lg font-heading font-bold text-charcoal-soft mb-4">
              Export Settings
            </h3>

            {/* Trim Size Selection */}
            <div className="mb-4">
              <Label className="mb-2">
                Book Size (Trim Size)
              </Label>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {[
                  { value: '6x9', label: '6" ├ù 9"', desc: 'Standard Novel' },
                  { value: '8.5x8.5', label: '8.5" ├ù 8.5"', desc: 'Square Picture Book' },
                  { value: '8x10', label: '8" ├ù 10"', desc: 'Premium Format' },
                  { value: '8.5x11', label: '8.5" ├ù 11"', desc: 'Large Format' },
                ].map((size) => (
                  <button
                    key={size.value}
                    onClick={() => setTrimSize(size.value as TrimSize)}
                    className={`p-4 rounded-xl border-2 transition-all text-left ${
                      trimSize === size.value
                        ? 'border-coral-burst bg-coral-burst/10'
                        : 'border-peach-soft hover:border-coral-burst/50'
                    }`}
                  >
                    <div className="font-bold text-charcoal-soft">{size.label}</div>
                    <div className="text-xs text-cocoa-light mt-1">{size.desc}</div>
                  </button>
                ))}
              </div>
            </div>

            {/* Bleed Option */}
            <div className="flex items-start gap-3 p-4 bg-cream-soft rounded-xl">
              <input
                type="checkbox"
                id="includeBleed"
                checked={includeBleed}
                onChange={(e) => setIncludeBleed(e.target.checked)}
                className="mt-1 w-5 h-5 text-coral-burst rounded focus:ring-coral-burst"
              />
              <Label htmlFor="includeBleed" className="flex-1 cursor-pointer">
                <div className="font-bold text-charcoal-soft">Include Bleed (Recommended)</div>
                <div className="text-sm text-cocoa-light mt-1">
                  Extends images 0.125" past trim edge for professional full-page illustrations
                </div>
              </Label>
            </div>

            {/* Advanced Options */}
            <button
              onClick={() => setShowAdvanced(!showAdvanced)}
              className="mt-4 text-sm text-coral-burst font-bold flex items-center gap-2 hover:underline"
            >
              <Settings className="w-4 h-4" />
              {showAdvanced ? 'Hide' : 'Show'} Advanced Options
            </button>

            {showAdvanced && (
              <div className="mt-4 p-4 bg-gray-50 rounded-xl space-y-3">
                <div className="text-sm">
                  <div className="font-bold text-charcoal-soft mb-2">Advanced Settings</div>
                  <div className="space-y-2 text-cocoa-light">
                    <div>Γ£ô Resolution: 300 DPI (Print Quality)</div>
                    <div>Γ£ô Color Mode: RGB (Auto-converted by KDP)</div>
                    <div>Γ£ô PDF Format: PDF/X-1a:2001</div>
                    <div>Γ£ô Fonts: Fully Embedded</div>
                    <div>Γ£ô Compression: Optimized</div>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Pre-flight Checklist */}
          {preview && preview.checklist && (
            <div className="mb-6">
              <h3 className="text-lg font-heading font-bold text-charcoal-soft mb-3">
                Pre-flight Checklist
              </h3>
              <div className="space-y-2">
                {preview.checklist.map((item: any, idx: number) => (
                  <div
                    key={idx}
                    className={`flex items-center gap-3 p-3 rounded-xl ${
                      item.status === 'pass'
                        ? 'bg-green-50 border border-green-200'
                        : item.status === 'warning'
                          ? 'bg-yellow-50 border border-yellow-200'
                          : 'bg-red-50 border border-red-200'
                    }`}
                  >
                    {item.status === 'pass' ? (
                      <CheckCircle className="w-5 h-5 text-green-600" />
                    ) : item.status === 'warning' ? (
                      <Info className="w-5 h-5 text-yellow-600" />
                    ) : (
                      <AlertCircle className="w-5 h-5 text-red-600" />
                    )}
                    <div className="flex-1">
                      <div className="font-bold text-sm text-charcoal-soft">{item.category}</div>
                      <div className="text-xs text-cocoa-light">{item.message}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Warnings */}
          {preview &&
            preview.validation &&
            preview.validation.warnings &&
            preview.validation.warnings.length > 0 && (
              <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-xl">
                <div className="flex items-start gap-3">
                  <Info className="w-5 h-5 text-yellow-600 mt-0.5" />
                  <div>
                    <div className="font-bold text-yellow-800 mb-2">Warnings</div>
                    <ul className="text-sm text-yellow-700 space-y-1">
                      {preview.validation.warnings.map((warning: string, idx: number) => (
                        <li key={idx}>ΓÇó {warning}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            )}

          {/* Tier Restriction */}
          {userTier === UserTier.SPARK && (
            <div className="mb-6 p-6 bg-gradient-to-r from-gold-sunshine/20 to-coral-burst/20 border-2 border-gold-sunshine rounded-2xl">
              <div className="flex items-center gap-3 mb-3">
                <div className="w-10 h-10 bg-gold-sunshine rounded-full flex items-center justify-center">
                  <FileText className="w-5 h-5 text-white" />
                </div>
                <div>
                  <div className="font-bold text-charcoal-soft">Premium Feature</div>
                  <div className="text-sm text-cocoa-light">Upgrade to unlock KDP export</div>
                </div>
              </div>
              <ul className="text-sm text-cocoa-light space-y-1 mb-4">
                <li>Γ£ô Professional print-ready PDFs</li>
                <li>Γ£ô Multiple trim sizes (6x9, 8.5x8.5, 8x10, 8.5x11)</li>
                <li>Γ£ô 300 DPI print quality</li>
                <li>Γ£ô Bleed support for full-page images</li>
                <li>Γ£ô Quality validation dashboard</li>
              </ul>
            </div>
          )}
          </div>
        </ScrollArea>

        {/* Footer */}
        <DialogFooter className="border-t-2 border-peach-soft/30 p-6 bg-cream-base flex-row items-center justify-between gap-4">
          <Button variant="outline" onClick={onClose} disabled={isExporting}>
            Cancel
          </Button>

          <Button
            onClick={handleExport}
            disabled={isExporting || userTier === UserTier.SPARK}
            size="lg"
            className="gap-2"
          >
            {isExporting ? (
              <>
                <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                <div className="flex flex-col items-start">
                  <span>{exportProgress}%</span>
                  <span className="text-xs text-white/80">{progressMessage}</span>
                </div>
              </>
            ) : (
              <>
                <Download className="w-5 h-5" />
                {userTier === UserTier.SPARK ? 'Upgrade to Export' : 'Export for Amazon KDP'}
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

// Quality Metric Component
const QualityMetric: React.FC<{ label: string; score: number; icon: string }> = ({
  label,
  score,
  icon,
}) => {
  const getColor = (score: number) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  return (
    <div className="bg-white rounded-xl p-3 border border-gray-200">
      <div className="flex items-center gap-2 mb-2">
        <span className="text-lg">{icon}</span>
        <span className="text-xs font-bold text-cocoa-light">{label}</span>
      </div>
      <div className={`text-2xl font-bold ${getColor(score)}`}>{score}%</div>
      <div className="w-full h-2 bg-gray-200 rounded-full mt-2 overflow-hidden">
        <div
          className={`h-full transition-all ${
            score >= 90 ? 'bg-green-500' : score >= 70 ? 'bg-yellow-500' : 'bg-red-500'
          }`}
          style={{ width: `${score}%` }}
        />
      </div>
    </div>
  );
};

