// Hook for managing style presets
export function useStylePresets() {
  const [presets, setPresets] = useState<StylePreset[]>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      const userPresets = stored ? JSON.parse(stored) : [];
      return [...BUILT_IN_PRESETS, ...userPresets];
    } catch {
      return BUILT_IN_PRESETS;
    }
  });

  // Save user presets to localStorage
  useEffect(() => {
    const userPresets = presets.filter((p) => !p.isBuiltIn);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(userPresets));
  }, [presets]);

  const addPreset = useCallback(
    (preset: Omit<StylePreset, 'id' | 'createdAt' | 'usageCount' | 'isBuiltIn'>) => {
      const newPreset: StylePreset = {
        ...preset,
        id: `custom-${Date.now()}`,
        createdAt: Date.now(),
        usageCount: 0,
        isBuiltIn: false,
      };
      setPresets((prev) => [...prev, newPreset]);
      return newPreset;
    },
    []
  );

  const updatePreset = useCallback((id: string, updates: Partial<StylePreset>) => {
    setPresets((prev) => prev.map((p) => (p.id === id && !p.isBuiltIn ? { ...p, ...updates } : p)));
  }, []);

  const deletePreset = useCallback((id: string) => {
    setPresets((prev) => prev.filter((p) => p.id !== id || p.isBuiltIn));
  }, []);

  const toggleFavorite = useCallback((id: string) => {
    setPresets((prev) => prev.map((p) => (p.id === id ? { ...p, isFavorite: !p.isFavorite } : p)));
  }, []);

  const incrementUsage = useCallback((id: string) => {
    setPresets((prev) =>
      prev.map((p) => (p.id === id ? { ...p, usageCount: p.usageCount + 1 } : p))
    );
  }, []);

  const favorites = presets.filter((p) => p.isFavorite);
  const recent = [...presets]
    .filter((p) => p.usageCount > 0)
    .sort((a, b) => b.usageCount - a.usageCount)
    .slice(0, 5);

  return {
    presets,
    favorites,
    recent,
    addPreset,
    updatePreset,
    deletePreset,
    toggleFavorite,
    incrementUsage,
  };
}

