// ==============================================================================
// ACTIVITY FEED COMPONENT
// ==============================================================================
// Real-time activity stream showing user actions
// ==============================================================================

import {
  ChevronDown,
  Clock,
  GitFork,
  Heart,
  Image,
  Loader2,
  MessageCircle,
  Star,
  Trophy,
  UserPlus,
  Users,
  Zap,
} from 'lucide-react';
import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { collaborationService } from '../../services/collaborationService';
import {
  type Activity,
  type ActivityType,
  REACTION_EMOJIS,
  type ReactionType,
} from '../../types/collaboration';
import { Button } from '@components/ui/button';

interface ActivityFeedProps {
  sessionId?: string;
  scope?: 'global' | 'session';
  maxHeight?: string;
  showHeader?: boolean;
  autoRefresh?: boolean;
  refreshInterval?: number;
  onActivityClick?: (activity: Activity) => void;
}

const ActivityFeed: React.FC<ActivityFeedProps> = ({
  sessionId,
  scope = 'session',
  maxHeight = '400px',
  showHeader = true,
  autoRefresh = true,
  refreshInterval = 30000,
  onActivityClick,
}) => {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [hasMore, setHasMore] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const feedRef = useRef<HTMLDivElement>(null);

  // Load activities
  const loadActivities = useCallback(
    async (append = false) => {
      if (append) setIsLoadingMore(true);
      else setIsLoading(true);

      try {
        const lastActivity =
          append && activities.length > 0 ? activities[activities.length - 1] : undefined;

        const data = await collaborationService.getActivities({
          scope,
          sessionId,
          limit: 20,
          before: lastActivity?.created_at,
        });

        if (append) {
          setActivities((prev) => [...prev, ...data]);
        } else {
          setActivities(data);
        }

        setHasMore(data.length === 20);
      } catch (error) {
        console.error('Error loading activities:', error);
      } finally {
        setIsLoading(false);
        setIsLoadingMore(false);
      }
    },
    [scope, sessionId, activities]
  );

  // Initial load
  useEffect(() => {
    loadActivities();
  }, [sessionId, scope]);

  // Auto refresh
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      loadActivities();
    }, refreshInterval);

    return () => clearInterval(interval);
  }, [autoRefresh, refreshInterval, loadActivities]);

  // Get activity icon
  const getActivityIcon = (type: ActivityType) => {
    switch (type) {
      case 'visual_created':
        return <Image className="w-4 h-4" />;
      case 'visual_remixed':
        return <GitFork className="w-4 h-4" />;
      case 'visual_featured':
        return <Star className="w-4 h-4 text-yellow-500" />;
      case 'reaction_added':
        return <Heart className="w-4 h-4 text-red-400" />;
      case 'annotation_added':
        return <MessageCircle className="w-4 h-4" />;
      case 'comment_added':
        return <MessageCircle className="w-4 h-4" />;
      case 'challenge_submitted':
        return <Trophy className="w-4 h-4 text-purple-500" />;
      case 'challenge_won':
        return <Trophy className="w-4 h-4 text-yellow-500" />;
      case 'user_joined':
        return <UserPlus className="w-4 h-4 text-green-500" />;
      case 'user_leveled_up':
        return <Zap className="w-4 h-4 text-blue-500" />;
      case 'collab_started':
        return <Users className="w-4 h-4 text-purple-500" />;
      case 'collab_joined':
        return <Users className="w-4 h-4 text-green-500" />;
      default:
        return <Clock className="w-4 h-4" />;
    }
  };

  // Get activity color
  const getActivityColor = (type: ActivityType): string => {
    switch (type) {
      case 'visual_created':
        return 'bg-coral-burst/10 text-coral-burst';
      case 'visual_remixed':
        return 'bg-purple-100 text-purple-600';
      case 'visual_featured':
        return 'bg-yellow-100 text-yellow-600';
      case 'reaction_added':
        return 'bg-red-100 text-red-500';
      case 'challenge_submitted':
        return 'bg-purple-100 text-purple-600';
      case 'challenge_won':
        return 'bg-yellow-100 text-yellow-600';
      case 'user_joined':
        return 'bg-green-100 text-green-600';
      case 'user_leveled_up':
        return 'bg-blue-100 text-blue-600';
      case 'collab_started':
        return 'bg-purple-100 text-purple-600';
      case 'collab_joined':
        return 'bg-green-100 text-green-600';
      default:
        return 'bg-gray-100 text-gray-600';
    }
  };

  // Get activity text
  const getActivityText = (activity: Activity): React.ReactNode => {
    const userName = activity.user?.full_name || 'Someone';

    switch (activity.type) {
      case 'visual_created':
        return (
          <>
            <strong>{userName}</strong> created a new visual
          </>
        );
      case 'visual_remixed':
        return (
          <>
            <strong>{userName}</strong> remixed a visual
          </>
        );
      case 'visual_featured':
        return (
          <>
            <strong>{userName}</strong>'s visual was featured! Γ¡É
          </>
        );
      case 'reaction_added':
        const emoji = activity.metadata?.reactionType
          ? REACTION_EMOJIS[activity.metadata.reactionType as ReactionType]
          : 'Γ¥ñ∩╕Å';
        return (
          <>
            <strong>{userName}</strong> reacted with {emoji}
          </>
        );
      case 'challenge_submitted':
        return (
          <>
            <strong>{userName}</strong> submitted to{' '}
            <span className="text-purple-600">
              {activity.metadata?.challengeTitle || 'a challenge'}
            </span>
          </>
        );
      case 'challenge_won':
        return (
          <>
            <strong>{userName}</strong> won{' '}
            <span className="text-yellow-600">
              {activity.metadata?.challengeTitle || 'a challenge'}
            </span>
            ! ≡ƒÅå
          </>
        );
      case 'user_joined':
        return (
          <>
            <strong>{userName}</strong> joined the session
          </>
        );
      case 'user_leveled_up':
        return (
          <>
            <strong>{userName}</strong> leveled up to{' '}
            <span className="text-blue-600">Level {activity.metadata?.newLevel}</span>! ≡ƒÄë
          </>
        );
      case 'collab_started':
        return (
          <>
            <strong>{userName}</strong> started a collaboration session
          </>
        );
      case 'collab_joined':
        return (
          <>
            <strong>{userName}</strong> joined the collaboration
          </>
        );
      default:
        return (
          <>
            <strong>{userName}</strong> did something
          </>
        );
    }
  };

  // Format time ago
  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffSecs = Math.floor(diffMs / 1000);
    const diffMins = Math.floor(diffSecs / 60);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffSecs < 60) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="bg-white rounded-xl sm:rounded-2xl border border-white overflow-hidden h-full flex flex-col">
      {showHeader && (
        <div className="flex items-center justify-between px-3 sm:px-4 py-2.5 sm:py-3 border-b border-gray-100 flex-shrink-0">
          <h3 className="font-heading font-bold text-sm sm:text-base text-charcoal-soft flex items-center gap-2">
            <Clock className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-coral-burst" />
            Activity
          </h3>
          <span className="text-[10px] sm:text-xs text-gray-400">
            {scope === 'session' ? 'This session' : 'Global'}
          </span>
        </div>
      )}

      <div
        ref={feedRef}
        className="overflow-y-auto flex-1 scroll-container pb-32 sm:pb-0"
        style={{ maxHeight: maxHeight !== '400px' ? maxHeight : undefined }}
      >
        {isLoading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-5 h-5 sm:w-6 sm:h-6 text-coral-burst animate-spin" />
          </div>
        ) : activities.length === 0 ? (
          <div className="text-center py-6 sm:py-8 text-gray-400">
            <Clock className="w-6 h-6 sm:w-8 sm:h-8 mx-auto mb-2 opacity-50" />
            <p className="text-xs sm:text-sm">No activity yet</p>
            <p className="text-[10px] sm:text-xs">Be the first to create something!</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-50">
            {activities.map((activity, index) => (
              <div
                key={activity.id}
                className={`
                                    flex items-start gap-2 sm:gap-3 px-3 sm:px-4 py-2.5 sm:py-3 
                                    hover:bg-gray-50 active:bg-gray-100 transition-colors cursor-pointer
                                    animate-fadeIn
                                `}
                style={{ animationDelay: `${Math.min(index * 50, 500)}ms` }}
                onClick={() => onActivityClick?.(activity)}
              >
                {/* User avatar */}
                <div className="relative flex-shrink-0">
                  <img
                    src={
                      activity.user?.avatar_url ||
                      `https://api.dicebear.com/7.x/avataaars/svg?seed=${activity.user_id}`
                    }
                    alt={activity.user?.full_name || 'User'}
                    className="w-7 h-7 sm:w-8 sm:h-8 rounded-full object-cover"
                  />
                  {/* Activity type icon */}
                  <span
                    className={`
                                        absolute -bottom-0.5 -right-0.5 
                                        w-4 h-4 sm:w-5 sm:h-5 rounded-full 
                                        flex items-center justify-center
                                        ring-2 ring-white
                                        ${getActivityColor(activity.type)}
                                    `}
                  >
                    {getActivityIcon(activity.type)}
                  </span>
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <p className="text-xs sm:text-sm text-charcoal-soft line-clamp-2">
                    {getActivityText(activity)}
                  </p>
                  <p className="text-[10px] sm:text-xs text-gray-400 mt-0.5">
                    {formatTimeAgo(activity.created_at)}
                  </p>
                </div>

                {/* Visual thumbnail if available */}
                {activity.visual && (
                  <img
                    src={activity.visual.thumbnail_url || activity.visual.image_url}
                    alt="Visual"
                    className="w-8 h-8 sm:w-10 sm:h-10 rounded-lg object-cover flex-shrink-0"
                  />
                )}
              </div>
            ))}

            {/* Load more button */}
            {hasMore && (
              <Button
                variant="ghost"
                onClick={() => loadActivities(true)}
                disabled={isLoadingMore}
                className="w-full py-3 text-center text-xs sm:text-sm text-coral-burst hover:bg-coral-burst/5 active:bg-coral-burst/10 flex min-h-[44px]"
              >
                {isLoadingMore ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <>
                    <ChevronDown className="w-4 h-4" />
                    Load more
                  </>
                )}
              </Button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// COMPACT ACTIVITY NOTIFICATION
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface ActivityNotificationProps {
  activity: Activity;
  onDismiss?: () => void;
}

export const ActivityNotification: React.FC<ActivityNotificationProps> = ({
  activity,
  onDismiss,
}) => {
  useEffect(() => {
    if (!onDismiss) return;
    const timer = setTimeout(onDismiss, 5000);
    return () => clearTimeout(timer);
  }, [onDismiss]);

  return (
    <div
      className="fixed bottom-28 sm:bottom-24 left-2 sm:left-4 right-2 sm:right-auto z-50 animate-slideUp"
      style={{ bottom: 'calc(7rem + env(safe-area-inset-bottom, 0px))' }}
    >
      <div className="bg-white rounded-xl border border-gray-200 p-2.5 sm:p-3 flex items-center gap-2 sm:gap-3 max-w-full sm:max-w-[300px]">
        <img
          src={
            activity.user?.avatar_url ||
            `https://api.dicebear.com/7.x/avataaars/svg?seed=${activity.user_id}`
          }
          alt=""
          className="w-7 h-7 sm:w-8 sm:h-8 rounded-full flex-shrink-0"
        />
        <div className="flex-1 min-w-0">
          <p className="text-xs sm:text-sm text-charcoal-soft truncate">
            <strong>{activity.user?.full_name || 'Someone'}</strong>{' '}
            {activity.type === 'visual_created' && 'created a new visual'}
            {activity.type === 'reaction_added' && 'reacted to a visual'}
            {activity.type === 'collab_joined' && 'joined the session'}
          </p>
        </div>
        {activity.visual && (
          <img
            src={activity.visual.thumbnail_url || activity.visual.image_url}
            alt=""
            className="w-7 h-7 sm:w-8 sm:h-8 rounded-lg object-cover flex-shrink-0"
          />
        )}
      </div>
    </div>
  );
};

export default ActivityFeed;

// ==============================================================================
// GENESIS BROADCAST STUDIO COMPONENT
// ==============================================================================
// Live streaming interface for broadcasters with viewer chat and controls
// ==============================================================================

import { AnimatePresence, motion } from 'framer-motion';
import {
  AlertCircle,
  Check,
  Clock,
  Copy,
  Eye,
  EyeOff,
  MessageSquare,
  Pin,
  PlayCircle,
  Radio,
  Send,
  Settings,
  Share2,
  StopCircle,
  Users,
  X,
} from 'lucide-react';
import type React from 'react';
import { useEffect, useRef, useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { broadcastService } from '../../services/broadcastService';
import type { BroadcastMessage, BroadcastSession, BroadcastViewer } from '../../types/advanced';
import { Button } from '@components/ui/button';
import { Input, Label } from '@components/ui/input';
import { Textarea } from '@components/ui/input';

interface BroadcastStudioProps {
  onClose?: () => void;
  initialSession?: BroadcastSession;
}

const BroadcastStudio: React.FC<BroadcastStudioProps> = ({ onClose, initialSession }) => {
  const { user } = useAuth();
  const [session, setSession] = useState<BroadcastSession | null>(initialSession || null);
  const [isLive, setIsLive] = useState(false);
  const [viewers, setViewers] = useState<BroadcastViewer[]>([]);
  const [messages, setMessages] = useState<BroadcastMessage[]>([]);
  const [questions, setQuestions] = useState<BroadcastMessage[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [activeTab, setActiveTab] = useState<'chat' | 'questions' | 'viewers'>('chat');
  const [showSettings, setShowSettings] = useState(false);
  const [settings, setSettings] = useState({
    chatEnabled: true,
    questionsEnabled: true,
    copySettingsEnabled: true,
    isPrivate: false,
  });
  const [stats, setStats] = useState({
    peakViewers: 0,
    totalMessages: 0,
    duration: 0,
  });
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Subscribe to broadcast events when live
  useEffect(() => {
    if (!session || !isLive) return;

    const channel = broadcastService.subscribeToBroadcast(session.id, {
      onViewerJoin: (viewer) => {
        setViewers((prev) => [...prev, viewer]);
        if (viewers.length + 1 > stats.peakViewers) {
          setStats((prev) => ({ ...prev, peakViewers: viewers.length + 1 }));
        }
      },
      onViewerLeave: (viewer) => {
        setViewers((prev) => prev.filter((v) => v.id !== viewer.id));
      },
      onMessage: (message) => {
        if (message.type === 'question') {
          setQuestions((prev) => [...prev, message]);
        } else {
          setMessages((prev) => [...prev, message]);
        }
        setStats((prev) => ({ ...prev, totalMessages: prev.totalMessages + 1 }));
      },
      onViewerCountChange: (count) => {
        if (count > stats.peakViewers) {
          setStats((prev) => ({ ...prev, peakViewers: count }));
        }
      },
    });

    // Start duration timer
    timerRef.current = setInterval(() => {
      setStats((prev) => ({ ...prev, duration: prev.duration + 1 }));
    }, 1000);

    return () => {
      broadcastService.unsubscribeFromBroadcast(session.id);
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [session, isLive]);

  // Auto-scroll messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleStartBroadcast = async () => {
    if (!title.trim()) {
      alert('Please enter a title for your broadcast');
      return;
    }

    const result = await broadcastService.startBroadcast(title, description, {
      chat_enabled: settings.chatEnabled,
      questions_enabled: settings.questionsEnabled,
      copy_settings_enabled: settings.copySettingsEnabled,
      is_private: settings.isPrivate,
    });

    if (result.success && result.data) {
      setSession(result.data);
      setIsLive(true);
    } else {
      alert(result.error || 'Failed to start broadcast');
    }
  };

  const handleEndBroadcast = async () => {
    if (!session) return;

    const confirmed = window.confirm('Are you sure you want to end this broadcast?');
    if (!confirmed) return;

    const result = await broadcastService.endBroadcast(session.id);
    if (result.success) {
      setIsLive(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const handleSendMessage = async () => {
    if (!session || !newMessage.trim()) return;

    await broadcastService.sendMessage(session.id, newMessage, 'chat');
    setNewMessage('');
  };

  const handlePinMessage = async (messageId: string, isPinned: boolean) => {
    await broadcastService.togglePinMessage(messageId, !isPinned);
    setMessages((prev) =>
      prev.map((m) => (m.id === messageId ? { ...m, is_pinned: !isPinned } : m))
    );
  };

  const handleAnswerQuestion = async (questionId: string) => {
    await broadcastService.markQuestionAnswered(questionId);
    setQuestions((prev) =>
      prev.map((q) => (q.id === questionId ? { ...q, is_answered: true } : q))
    );
  };

  const formatDuration = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const copyShareLink = () => {
    if (session) {
      navigator.clipboard.writeText(`${window.location.origin}/broadcast/${session.id}`);
    }
  };

  return (
    <div className="flex flex-col h-full bg-gray-900 rounded-2xl overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-gradient-to-r from-purple-900/30 to-pink-900/30">
        <div className="flex items-center gap-4">
          {isLive ? (
            <div className="flex items-center gap-2">
              <motion.div
                animate={{ scale: [1, 1.2, 1] }}
                transition={{ duration: 1.5, repeat: Number.POSITIVE_INFINITY }}
                className="w-3 h-3 bg-red-500 rounded-full"
              />
              <span className="font-bold text-red-400">LIVE</span>
            </div>
          ) : (
            <div className="flex items-center gap-2 text-gray-400">
              <Radio className="w-5 h-5 opacity-50" />
              <span>Offline</span>
            </div>
          )}

          {isLive && session && (
            <>
              <div className="flex items-center gap-2 text-gray-300">
                <Clock className="w-4 h-4" />
                <span className="font-mono">{formatDuration(stats.duration)}</span>
              </div>
              <div className="flex items-center gap-2 text-gray-300">
                <Users className="w-4 h-4" />
                <span>{session.viewer_count}</span>
              </div>
            </>
          )}
        </div>

        <div className="flex items-center gap-2">
          {isLive && (
            <>
              <Button
                variant="ghost"
                size="icon"
                onClick={copyShareLink}
                className="p-2 hover:bg-white/10"
                title="Copy share link"
              >
                <Share2 className="w-5 h-5 text-gray-400" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setShowSettings(!showSettings)}
                className="p-2 hover:bg-white/10"
              >
                <Settings className="w-5 h-5 text-gray-400" />
              </Button>
            </>
          )}
          {onClose && (
            <Button
              variant="ghost"
              size="icon"
              onClick={onClose}
              className="p-2 hover:bg-white/10"
            >
              <X className="w-5 h-5 text-gray-400" />
            </Button>
          )}
        </div>
      </div>

      {/* Main content */}
      <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">
        {/* Left panel - Broadcast setup or preview */}
        <div className="flex-1 flex flex-col min-h-0">
          {isLive ? (
            /* Live broadcast info */
            <div className="flex-1 overflow-y-auto p-6">
              <div className="bg-white/5 rounded-2xl p-6 mb-6">
                <h3 className="text-xl font-bold text-white mb-2">{session?.title}</h3>
                {session?.description && <p className="text-gray-400">{session.description}</p>}
              </div>

              {/* Stats cards */}
              <div className="grid grid-cols-3 gap-4 mb-6">
                <div className="bg-gradient-to-br from-purple-500/20 to-purple-600/10 rounded-xl p-4">
                  <div className="flex items-center gap-2 text-purple-400 mb-1">
                    <Users className="w-4 h-4" />
                    <span className="text-sm">Peak Viewers</span>
                  </div>
                  <p className="text-2xl font-bold text-white">{stats.peakViewers}</p>
                </div>
                <div className="bg-gradient-to-br from-pink-500/20 to-pink-600/10 rounded-xl p-4">
                  <div className="flex items-center gap-2 text-pink-400 mb-1">
                    <MessageSquare className="w-4 h-4" />
                    <span className="text-sm">Messages</span>
                  </div>
                  <p className="text-2xl font-bold text-white">{stats.totalMessages}</p>
                </div>
                <div className="bg-gradient-to-br from-cyan-500/20 to-cyan-600/10 rounded-xl p-4">
                  <div className="flex items-center gap-2 text-cyan-400 mb-1">
                    <Clock className="w-4 h-4" />
                    <span className="text-sm">Duration</span>
                  </div>
                  <p className="text-2xl font-bold text-white font-mono">
                    {formatDuration(stats.duration)}
                  </p>
                </div>
              </div>

              {/* End broadcast button */}
              <Button
                variant="destructive"
                size="lg"
                onClick={handleEndBroadcast}
                className="w-full bg-red-500/20 border border-red-500/50 text-red-400 flex gap-3 hover:bg-red-500/30"
              >
                <StopCircle className="w-6 h-6" />
                End Broadcast
              </Button>
            </div>
          ) : (
            /* Pre-broadcast setup */
            <div className="flex-1 overflow-y-auto p-8">
              <div className="min-h-full flex items-center justify-center">
                <div className="max-w-md w-full space-y-6">
                  <div className="text-center">
                    <div className="w-20 h-20 mx-auto mb-4 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full flex items-center justify-center">
                      <Radio className="w-10 h-10 text-white" />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Go Live</h2>
                    <p className="text-gray-400">Share your creative process with the community</p>
                  </div>

                  <div className="space-y-4">
                    <div>
                      <Label className="text-gray-300 mb-2">
                        Broadcast Title *
                      </Label>
                      <Input
                        type="text"
                        value={title}
                        onChange={(e) => setTitle(e.target.value)}
                        placeholder="What are you creating today?"
                        className="py-3 bg-white/5 border-white/10 text-white placeholder-gray-500 focus:border-purple-500"
                      />
                    </div>

                    <div>
                      <Label className="text-gray-300 mb-2">
                        Description (optional)
                      </Label>
                      <Textarea
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                        placeholder="Tell viewers what to expect..."
                        rows={3}
                        className="bg-white/5 border-white/10 text-white placeholder-gray-500 focus:border-purple-500 transition-colors"
                      />
                    </div>

                    {/* Settings toggles */}
                    <div className="space-y-3 pt-4 border-t border-white/10">
                      <Label className="flex items-center justify-between cursor-pointer group">
                        <div className="flex items-center gap-3">
                          <MessageSquare className="w-5 h-5 text-gray-400" />
                          <span className="text-gray-300">Enable chat</span>
                        </div>
                        <div
                          onClick={() =>
                            setSettings((s) => ({ ...s, chatEnabled: !s.chatEnabled }))
                          }
                          className={`w-11 h-6 rounded-full transition-colors ${
                            settings.chatEnabled ? 'bg-purple-500' : 'bg-gray-600'
                          }`}
                        >
                          <motion.div
                            animate={{ x: settings.chatEnabled ? 20 : 2 }}
                            className="w-5 h-5 bg-white rounded-full mt-0.5"
                          />
                        </div>
                      </Label>

                      <Label className="flex items-center justify-between cursor-pointer group">
                        <div className="flex items-center gap-3">
                          <AlertCircle className="w-5 h-5 text-gray-400" />
                          <span className="text-gray-300">Allow questions</span>
                        </div>
                        <div
                          onClick={() =>
                            setSettings((s) => ({ ...s, questionsEnabled: !s.questionsEnabled }))
                          }
                          className={`w-11 h-6 rounded-full transition-colors ${
                            settings.questionsEnabled ? 'bg-purple-500' : 'bg-gray-600'
                          }`}
                        >
                          <motion.div
                            animate={{ x: settings.questionsEnabled ? 20 : 2 }}
                            className="w-5 h-5 bg-white rounded-full mt-0.5"
                          />
                        </div>
                      </Label>

                      <Label className="flex items-center justify-between cursor-pointer group">
                        <div className="flex items-center gap-3">
                          <Copy className="w-5 h-5 text-gray-400" />
                          <span className="text-gray-300">Allow copying settings</span>
                        </div>
                        <div
                          onClick={() =>
                            setSettings((s) => ({
                              ...s,
                              copySettingsEnabled: !s.copySettingsEnabled,
                            }))
                          }
                          className={`w-11 h-6 rounded-full transition-colors ${
                            settings.copySettingsEnabled ? 'bg-purple-500' : 'bg-gray-600'
                          }`}
                        >
                          <motion.div
                            animate={{ x: settings.copySettingsEnabled ? 20 : 2 }}
                            className="w-5 h-5 bg-white rounded-full mt-0.5"
                          />
                        </div>
                      </Label>

                      <Label className="flex items-center justify-between cursor-pointer group">
                        <div className="flex items-center gap-3">
                          {settings.isPrivate ? (
                            <EyeOff className="w-5 h-5 text-gray-400" />
                          ) : (
                            <Eye className="w-5 h-5 text-gray-400" />
                          )}
                          <span className="text-gray-300">Private broadcast</span>
                        </div>
                        <div
                          onClick={() => setSettings((s) => ({ ...s, isPrivate: !s.isPrivate }))}
                          className={`w-11 h-6 rounded-full transition-colors ${
                            settings.isPrivate ? 'bg-purple-500' : 'bg-gray-600'
                          }`}
                        >
                          <motion.div
                            animate={{ x: settings.isPrivate ? 20 : 2 }}
                            className="w-5 h-5 bg-white rounded-full mt-0.5"
                          />
                        </div>
                      </Label>
                    </div>
                  </div>

                  <Button
                    variant="primary"
                    size="lg"
                    onClick={handleStartBroadcast}
                    disabled={!title.trim()}
                    className="w-full bg-gradient-to-r from-red-500 to-pink-500 text-white flex gap-3 hover:opacity-90 transition-opacity disabled:cursor-not-allowed"
                  >
                    <PlayCircle className="w-6 h-6" />
                    Start Broadcasting
                  </Button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Right panel - Chat/Questions/Viewers */}
        {isLive && (
          <div className="w-full lg:w-80 border-t lg:border-t-0 lg:border-l border-white/10 flex flex-col h-[40%] lg:h-auto">
            {/* Tabs */}
            <div className="flex border-b border-white/10">
              <Button
                variant="ghost"
                onClick={() => setActiveTab('chat')}
                className={`flex-1 py-3 font-medium relative ${
                  activeTab === 'chat' ? 'text-purple-400' : 'text-gray-400 hover:text-white'
                }`}
              >
                Chat
                {activeTab === 'chat' && (
                  <motion.div
                    layoutId="activeTab"
                    className="absolute bottom-0 left-0 right-0 h-0.5 bg-purple-500"
                  />
                )}
              </Button>
              <Button
                variant="ghost"
                onClick={() => setActiveTab('questions')}
                className={`flex-1 py-3 font-medium relative ${
                  activeTab === 'questions' ? 'text-purple-400' : 'text-gray-400 hover:text-white'
                }`}
              >
                Questions
                {questions.filter((q) => !q.is_answered).length > 0 && (
                  <span className="ml-1 px-1.5 py-0.5 bg-orange-500 text-white text-xs rounded-full">
                    {questions.filter((q) => !q.is_answered).length}
                  </span>
                )}
                {activeTab === 'questions' && (
                  <motion.div
                    layoutId="activeTab"
                    className="absolute bottom-0 left-0 right-0 h-0.5 bg-purple-500"
                  />
                )}
              </Button>
              <Button
                variant="ghost"
                onClick={() => setActiveTab('viewers')}
                className={`flex-1 py-3 font-medium relative ${
                  activeTab === 'viewers' ? 'text-purple-400' : 'text-gray-400 hover:text-white'
                }`}
              >
                Viewers
                {activeTab === 'viewers' && (
                  <motion.div
                    layoutId="activeTab"
                    className="absolute bottom-0 left-0 right-0 h-0.5 bg-purple-500"
                  />
                )}
              </Button>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto p-4">
              <AnimatePresence mode="wait">
                {activeTab === 'chat' && (
                  <motion.div
                    key="chat"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="space-y-3"
                  >
                    {messages.map((msg) => (
                      <div
                        key={msg.id}
                        className={`p-3 rounded-lg ${
                          msg.is_pinned
                            ? 'bg-yellow-500/10 border border-yellow-500/30'
                            : 'bg-white/5'
                        }`}
                      >
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-sm font-medium text-purple-400">
                            {(msg.user as any)?.full_name || 'Anonymous'}
                          </span>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handlePinMessage(msg.id, msg.is_pinned)}
                            className={`p-1 rounded hover:bg-white/10 ${
                              msg.is_pinned ? 'text-yellow-400' : 'text-gray-500'
                            }`}
                          >
                            <Pin className="w-3 h-3" />
                          </Button>
                        </div>
                        <p className="text-sm text-gray-300">{msg.message}</p>
                      </div>
                    ))}
                    <div ref={messagesEndRef} />
                  </motion.div>
                )}

                {activeTab === 'questions' && (
                  <motion.div
                    key="questions"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="space-y-3"
                  >
                    {questions.map((q) => (
                      <div
                        key={q.id}
                        className={`p-3 rounded-lg ${
                          q.is_answered ? 'bg-green-500/10 opacity-60' : 'bg-orange-500/10'
                        }`}
                      >
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-sm font-medium text-orange-400">
                            {(q.user as any)?.full_name || 'Anonymous'}
                          </span>
                          {!q.is_answered && (
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleAnswerQuestion(q.id)}
                              className="p-1 text-gray-400 hover:text-green-400 rounded hover:bg-white/10"
                              title="Mark as answered"
                            >
                              <Check className="w-4 h-4" />
                            </Button>
                          )}
                        </div>
                        <p className="text-sm text-gray-300">{q.message}</p>
                        {q.is_answered && (
                          <span className="text-xs text-green-400 mt-1 flex items-center gap-1">
                            <Check className="w-3 h-3" /> Answered
                          </span>
                        )}
                      </div>
                    ))}
                    {questions.length === 0 && (
                      <div className="text-center text-gray-500 py-8">
                        <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p className="text-sm">No questions yet</p>
                      </div>
                    )}
                  </motion.div>
                )}

                {activeTab === 'viewers' && (
                  <motion.div
                    key="viewers"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="space-y-2"
                  >
                    {viewers.map((viewer) => (
                      <div
                        key={viewer.id}
                        className="flex items-center gap-3 p-2 rounded-lg hover:bg-white/5"
                      >
                        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                          {(viewer.viewer as any)?.avatar_url ? (
                            <img
                              src={(viewer.viewer as any).avatar_url}
                              alt=""
                              className="w-full h-full rounded-full object-cover"
                            />
                          ) : (
                            <span className="text-white text-sm font-medium">
                              {((viewer.viewer as any)?.full_name || 'A')[0].toUpperCase()}
                            </span>
                          )}
                        </div>
                        <span className="text-sm text-gray-300">
                          {(viewer.viewer as any)?.full_name || 'Anonymous'}
                        </span>
                      </div>
                    ))}
                    {viewers.length === 0 && (
                      <div className="text-center text-gray-500 py-8">
                        <Users className="w-8 h-8 mx-auto mb-2 opacity-50" />
                        <p className="text-sm">No viewers yet</p>
                      </div>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            {/* Message input */}
            {activeTab === 'chat' && settings.chatEnabled && (
              <div className="p-4 border-t border-white/10">
                <div className="flex gap-2">
                  <Input
                    type="text"
                    value={newMessage}
                    onChange={(e) => setNewMessage(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                    placeholder="Send a message..."
                    className="flex-1 py-2 bg-white/5 border-white/10 text-white placeholder-gray-500 focus:border-purple-500"
                  />
                  <Button
                    variant="default"
                    size="icon"
                    onClick={handleSendMessage}
                    disabled={!newMessage.trim()}
                    className="p-2 bg-purple-500 hover:bg-purple-600"
                  >
                    <Send className="w-5 h-5 text-white" />
                  </Button>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default BroadcastStudio;

// ==============================================================================
// CHALLENGE CARD COMPONENT
// ==============================================================================
// Daily challenges display with timer, submissions, and leaderboard
// ==============================================================================

import {
  Award,
  ChevronRight,
  Clock,
  Crown,
  ImageIcon,
  Medal,
  Star,
  Target,
  ThumbsUp,
  Trophy,
  Users,
  Zap,
} from 'lucide-react';
import type React from 'react';
import { useEffect, useMemo, useState } from 'react';
import { collaborationService } from '../../services/collaborationService';
import type {
  Challenge,
  ChallengeDifficulty,
  ChallengeSubmission,
} from '../../types/collaboration';
import { Button } from '@components/ui/button';

interface ChallengeCardProps {
  challenge: Challenge;
  variant?: 'card' | 'banner' | 'compact';
  showSubmissions?: boolean;
  onJoin?: (challenge: Challenge) => void;
  onViewDetails?: (challenge: Challenge) => void;
  onVote?: (submission: ChallengeSubmission) => void;
}

const ChallengeCard: React.FC<ChallengeCardProps> = ({
  challenge,
  variant = 'card',
  showSubmissions = false,
  onJoin,
  onViewDetails,
  onVote,
}) => {
  const [timeRemaining, setTimeRemaining] = useState<number>(0);
  const [submissions, setSubmissions] = useState<ChallengeSubmission[]>(
    challenge.top_submissions || []
  );
  const [isLoading, setIsLoading] = useState(false);

  // Calculate time remaining
  useEffect(() => {
    const updateTime = () => {
      const now = Date.now();
      const endTime = new Date(challenge.ends_at).getTime();
      setTimeRemaining(Math.max(0, endTime - now));
    };

    updateTime();
    const interval = setInterval(updateTime, 1000);
    return () => clearInterval(interval);
  }, [challenge.ends_at]);

  // Format time remaining
  const formatTime = useMemo(() => {
    if (timeRemaining <= 0) return 'Ended';

    const hours = Math.floor(timeRemaining / 3600000);
    const minutes = Math.floor((timeRemaining % 3600000) / 60000);
    const seconds = Math.floor((timeRemaining % 60000) / 1000);

    if (hours >= 24) {
      const days = Math.floor(hours / 24);
      return `${days}d ${hours % 24}h`;
    }

    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }, [timeRemaining]);

  // Get difficulty color and label
  const getDifficultyConfig = (difficulty: ChallengeDifficulty) => {
    switch (difficulty) {
      case 'easy':
        return { color: 'bg-green-100 text-green-600', label: 'Easy', stars: 1 };
      case 'medium':
        return { color: 'bg-yellow-100 text-yellow-600', label: 'Medium', stars: 2 };
      case 'hard':
        return { color: 'bg-orange-100 text-orange-600', label: 'Hard', stars: 3 };
      case 'expert':
        return { color: 'bg-red-100 text-red-600', label: 'Expert', stars: 4 };
      default:
        return { color: 'bg-gray-100 text-gray-600', label: 'Unknown', stars: 0 };
    }
  };

  const difficultyConfig = getDifficultyConfig(challenge.difficulty);

  // Get status color
  const getStatusColor = () => {
    switch (challenge.status) {
      case 'active':
        return 'bg-green-500';
      case 'voting':
        return 'bg-purple-500';
      case 'upcoming':
        return 'bg-blue-500';
      case 'completed':
        return 'bg-gray-500';
      default:
        return 'bg-gray-500';
    }
  };

  // Handle vote
  const handleVote = async (submission: ChallengeSubmission) => {
    if (isLoading) return;
    setIsLoading(true);

    try {
      await collaborationService.voteForSubmission(submission.id);
      // Update local state
      setSubmissions((prev) =>
        prev.map((s) => (s.id === submission.id ? { ...s, vote_count: s.vote_count + 1 } : s))
      );
      onVote?.(submission);
    } catch (error) {
