};

const getChangeIndicator = (change: number) => {
  if (change > 0) return { icon: ArrowUp, color: 'text-green-400' };
  if (change < 0) return { icon: ArrowDown, color: 'text-red-400' };
  return { icon: Minus, color: 'text-gray-400' };
};

