/**
 * LiveCursors Component
 * Shows real-time cursor positions of all collaborators
 */

import React from 'react';
import { useOthers, useSelf } from '../../services/collaboration/liveblocks.config';

interface CursorProps {
  x: number;
  y: number;
  color: string;
  name: string;
}

function Cursor({ x, y, color, name }: CursorProps) {
  return (
    <div
      className="pointer-events-none absolute z-[9999] transition-transform duration-[20ms]"
      style={{
        transform: `translate(${x}px, ${y}px)`,
      }}
    >
      {/* Cursor arrow */}
      <svg
        width="20"
        height="20"
        viewBox="0 0 20 20"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        style={{ transform: 'rotate(-10deg)' }}
      >
        <path
          d="M3.5 3.5L3.5 16.5L7.5 12.5L12 17L14 15L9.5 10.5L14.5 10.5L3.5 3.5Z"
          fill={color}
          stroke="white"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
      </svg>

      {/* Name badge */}
      <div
        className="absolute left-4 top-4 px-2 py-1 rounded-full text-[11px] font-medium text-white whitespace-nowrap"
        style={{ backgroundColor: color }}
      >
        {name}
      </div>
    </div>
  );
}

interface LiveCursorsProps {
  /** Container element for relative positioning */
  containerRef?: React.RefObject<HTMLElement | null>;
}

export function LiveCursors({ containerRef }: LiveCursorsProps) {
  const others = useOthers();

  return (
    <>
      {others
        .filter((other) => other.presence?.cursor != null)
        .map((other) => (
          <Cursor
            key={other.connectionId}
            x={other.presence!.cursor!.x}
            y={other.presence!.cursor!.y}
            color={other.presence?.color || other.info?.color || '#6366F1'}
            name={other.info?.name || other.presence?.displayName || 'Anonymous'}
          />
        ))}
    </>
  );
}

/**
 * Hook to track cursor position and update presence
 */
export function useCursorTracking(containerRef: React.RefObject<HTMLElement | null>) {
  const self = useSelf();

  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Track cursor position
    const handlePointerMove = (e: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Update presence via the updateMyPresence from the parent
      const event = new CustomEvent('cursor-move', { detail: { x, y } });
      container.dispatchEvent(event);
    };

    const handlePointerLeave = () => {
      const event = new CustomEvent('cursor-leave');
      container.dispatchEvent(event);
    };

    container.addEventListener('pointermove', handlePointerMove);
    container.addEventListener('pointerleave', handlePointerLeave);

    return () => {
      container.removeEventListener('pointermove', handlePointerMove);
      container.removeEventListener('pointerleave', handlePointerLeave);
    };
  }, [containerRef]);
}

export default LiveCursors;

// ==============================================================================
// PRESENCE INDICATOR COMPONENT
// ==============================================================================
// Shows online users with status indicators and floating avatars
// ==============================================================================

import { Check, Coffee, Loader2, Pencil, Users } from 'lucide-react';
import type React from 'react';
import { useState } from 'react';
import type { CollaboratorStatus, PresenceUser } from '../../types/collaboration';

interface PresenceIndicatorProps {
  users: PresenceUser[];
  currentUserId?: string;
  maxVisible?: number;
  size?: 'sm' | 'md' | 'lg';
  showStatus?: boolean;
  showTooltip?: boolean;
  onClick?: () => void;
}

const PresenceIndicator: React.FC<PresenceIndicatorProps> = ({
  users,
  currentUserId,
  maxVisible = 5,
  size = 'md',
  showStatus = true,
  showTooltip = true,
  onClick,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // Size configurations
  const sizeConfig = {
    sm: { avatar: 'w-6 h-6', status: 'w-2 h-2', text: 'text-xs', ring: 'ring-1' },
    md: { avatar: 'w-8 h-8', status: 'w-3 h-3', text: 'text-sm', ring: 'ring-2' },
    lg: { avatar: 'w-10 h-10', status: 'w-4 h-4', text: 'text-base', ring: 'ring-2' },
  };

  const config = sizeConfig[size];

  // Filter out current user and sort by status
  const otherUsers = users.filter((u) => u.user_id !== currentUserId);
  const sortedUsers = [...otherUsers].sort((a, b) => {
    const statusOrder: Record<CollaboratorStatus, number> = {
      generating: 0,
      typing: 1,
      idle: 2,
      done: 3,
      away: 4,
    };
    return statusOrder[a.status] - statusOrder[b.status];
  });

  const visibleUsers = sortedUsers.slice(0, maxVisible);
  const remainingCount = sortedUsers.length - maxVisible;

  const getStatusColor = (status: CollaboratorStatus): string => {
    switch (status) {
      case 'generating':
        return 'bg-purple-500';
      case 'typing':
        return 'bg-blue-500';
      case 'done':
        return 'bg-green-500';
      case 'idle':
        return 'bg-gray-400';
      case 'away':
        return 'bg-yellow-500';
      default:
        return 'bg-gray-400';
    }
  };

  const getStatusIcon = (status: CollaboratorStatus) => {
    switch (status) {
      case 'generating':
        return <Loader2 className="w-3 h-3 animate-spin" />;
      case 'typing':
        return <Pencil className="w-3 h-3" />;
      case 'done':
        return <Check className="w-3 h-3" />;
      case 'away':
        return <Coffee className="w-3 h-3" />;
      default:
        return null;
    }
  };

  const getStatusLabel = (status: CollaboratorStatus): string => {
    switch (status) {
      case 'generating':
        return 'Generating...';
      case 'typing':
        return 'Typing...';
      case 'done':
        return 'Just finished';
      case 'idle':
        return 'Online';
      case 'away':
        return 'Away';
      default:
        return 'Online';
    }
  };

  if (sortedUsers.length === 0) {
    return (
      <div className="flex items-center gap-2 text-gray-400">
        <Users className="w-4 h-4" />
        <span className={config.text}>Just you</span>
      </div>
    );
  }

  return (
    <div className="relative">
      {/* Stacked avatars */}
      <div
        className="flex items-center cursor-pointer"
        onClick={() => (onClick ? onClick() : setIsExpanded(!isExpanded))}
      >
        <div className="flex -space-x-2">
          {visibleUsers.map((user, index) => (
            <div
              key={user.user_id}
              className={`
                                relative ${config.avatar} rounded-full 
                                ${config.ring} ring-white
                                transition-transform hover:scale-110 hover:z-10
                            `}
              style={{ zIndex: visibleUsers.length - index }}
              title={
                showTooltip ? `${user.display_name} - ${getStatusLabel(user.status)}` : undefined
              }
            >
              <img
                src={user.avatar_url}
                alt={user.display_name}
                className={`${config.avatar} rounded-full object-cover`}
              />

              {/* Status indicator */}
              {showStatus && (
                <span
                  className={`
                                    absolute -bottom-0.5 -right-0.5 
                                    ${config.status} rounded-full 
                                    ${getStatusColor(user.status)}
                                    ring-2 ring-white
                                    ${user.status === 'generating' ? 'animate-pulse' : ''}
                                `}
                />
              )}
            </div>
          ))}

          {/* Overflow count */}
          {remainingCount > 0 && (
            <div
              className={`
                            ${config.avatar} rounded-full 
                            bg-gray-200 ${config.ring} ring-white
                            flex items-center justify-center
                            font-bold ${config.text} text-gray-600
                        `}
            >
              +{remainingCount}
            </div>
          )}
        </div>

        {/* Online count label */}
        <span className={`ml-2 ${config.text} text-gray-500`}>{sortedUsers.length} online</span>
      </div>

      {/* Expanded user list */}
      {isExpanded && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsExpanded(false)} />
          <div className="absolute top-full left-0 mt-2 z-50 animate-fadeIn">
            <div className="bg-white rounded-xl border border-gray-200 py-2 min-w-[200px] max-h-[300px] overflow-y-auto">
              <div className="px-3 py-1 border-b border-gray-100 mb-1">
                <span className="text-xs font-bold text-gray-400 uppercase">
                  {sortedUsers.length} Collaborators Online
                </span>
              </div>

              {sortedUsers.map((user) => (
                <div
                  key={user.user_id}
                  className="flex items-center gap-3 px-3 py-2 hover:bg-gray-50"
                >
                  <div className="relative">
                    <img
                      src={user.avatar_url}
                      alt={user.display_name}
                      className="w-8 h-8 rounded-full object-cover"
                    />
                    <span
                      className={`
                                            absolute -bottom-0.5 -right-0.5 
                                            w-3 h-3 rounded-full 
                                            ${getStatusColor(user.status)}
                                            ring-2 ring-white
                                        `}
                    />
                  </div>

                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-charcoal-soft truncate">
                      {user.display_name}
                    </p>
                    <div className="flex items-center gap-1 text-xs text-gray-400">
                      {getStatusIcon(user.status)}
                      <span>{getStatusLabel(user.status)}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </>
      )}
    </div>
  );
};

