  Crown,
  Download,
  Eye,
  Flag,
  GitFork,
  Maximize2,
  MoreHorizontal,
  Share2,
  Sparkles,
} from 'lucide-react';
import type React from 'react';
import { useCallback, useState } from 'react';
import { REACTION_EMOJIS, type ReactionCount, type SharedVisual } from '../../types/collaboration';
import ReactionBar, { MiniReactionDisplay } from './ReactionBar';
import { Button } from '@components/ui/button';

interface SharedVisualCardProps {
  visual: SharedVisual;
  variant?: 'grid' | 'compact' | 'featured' | 'detail';
  showReactions?: boolean;
  showActions?: boolean;
  showUser?: boolean;
  onRemix?: (visual: SharedVisual) => void;
  onExpand?: (visual: SharedVisual) => void;
  onViewLineage?: (visual: SharedVisual) => void;
  onUserClick?: (userId: string) => void;
}

const SharedVisualCard: React.FC<SharedVisualCardProps> = ({
  visual,
  variant = 'grid',
  showReactions = true,
  showActions = true,
  showUser = true,
  onRemix,
  onExpand,
  onViewLineage,
  onUserClick,
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [reactions, setReactions] = useState<ReactionCount[]>([]);

  // Format numbers
  const formatCount = (count: number): string => {
    if (count >= 1000000) return `${(count / 1000000).toFixed(1)}M`;
    if (count >= 1000) return `${(count / 1000).toFixed(1)}K`;
    return count.toString();
  };

  // Format time ago
  const formatTimeAgo = (dateString: string): string => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 60) return `${diffMins}m`;
    if (diffHours < 24) return `${diffHours}h`;
    if (diffDays < 7) return `${diffDays}d`;
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  const handleDownload = useCallback(() => {
    const link = document.createElement('a');
