        className={`absolute top-0 right-0 w-64 h-64 bg-gradient-to-br ${tier.gradient} opacity-5 blur-3xl rounded-full -translate-y-1/2 translate-x-1/2`}
      />
      <div
        className={`absolute bottom-0 left-0 w-48 h-48 bg-gradient-to-tr ${tier.gradient} opacity-5 blur-2xl rounded-full translate-y-1/2 -translate-x-1/3`}
