import { useCallback, useEffect, useState } from 'react';

interface NetworkStatus {
  isOnline: boolean;
  isSlowConnection: boolean;
  connectionType: string | null;
  downlink: number | null;
  rtt: number | null;
  saveData: boolean;
}

export function useNetworkStatus(): NetworkStatus & {
  checkConnection: () => Promise<boolean>;
} {
  const [status, setStatus] = useState<NetworkStatus>(() => ({
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    isSlowConnection: false,
    connectionType: null,
    downlink: null,
    rtt: null,
    saveData: false,
  }));

  // Get connection info from Network Information API
  const getConnectionInfo = useCallback(() => {
    const connection =
      (navigator as any).connection ||
      (navigator as any).mozConnection ||
      (navigator as any).webkitConnection;

    if (connection) {
      return {
        connectionType: connection.effectiveType || connection.type || null,
        downlink: connection.downlink || null,
        rtt: connection.rtt || null,
        saveData: connection.saveData || false,
        isSlowConnection:
          connection.effectiveType === 'slow-2g' ||
          connection.effectiveType === '2g' ||
          (connection.rtt && connection.rtt > 500),
      };
    }
    return {
      connectionType: null,
      downlink: null,
      rtt: null,
      saveData: false,
      isSlowConnection: false,
    };
  }, []);

  // Ping server to verify actual connectivity
  const checkConnection = useCallback(async (): Promise<boolean> => {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);

      const response = await fetch('/api/health', {
        method: 'HEAD',
        cache: 'no-store',
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      return response.ok;
    } catch {
      // Fallback: try to fetch a small resource
      try {
        await fetch('/favicon.ico', {
          method: 'HEAD',
          cache: 'no-store',
        });
        return true;
      } catch {
        return false;
      }
    }
  }, []);

  useEffect(() => {
    const updateStatus = () => {
      const connectionInfo = getConnectionInfo();
      setStatus((prev) => ({
        ...prev,
        isOnline: navigator.onLine,
        ...connectionInfo,
      }));
    };

    // Listen for online/offline events
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);

    // Listen for connection changes
    const connection =
      (navigator as any).connection ||
      (navigator as any).mozConnection ||
      (navigator as any).webkitConnection;

    if (connection) {
      connection.addEventListener('change', updateStatus);
    }

    // Initial check
    updateStatus();

    return () => {
      window.removeEventListener('online', updateStatus);
      window.removeEventListener('offline', updateStatus);
      if (connection) {
        connection.removeEventListener('change', updateStatus);
      }
    };
  }, [getConnectionInfo]);

  return { ...status, checkConnection };
}

import { AnimatePresence, motion } from 'framer-motion';
import { AlertTriangle, RefreshCw, Wifi, WifiOff } from 'lucide-react';
// React component for offline indicator
import React from 'react';
import { Button } from '../components/ui/button';

interface OfflineIndicatorProps {
  position?: 'top' | 'bottom';
  showWhenOnline?: boolean;
}

export const OfflineIndicator: React.FC<OfflineIndicatorProps> = ({
  position = 'bottom',
  showWhenOnline = false,
}) => {
  const { isOnline, isSlowConnection, checkConnection } = useNetworkStatus();
  const [isChecking, setIsChecking] = React.useState(false);
  const [showOnlineMessage, setShowOnlineMessage] = React.useState(false);

  // Show "back online" message briefly when reconnecting
  useEffect(() => {
    if (isOnline && !showWhenOnline) {
      setShowOnlineMessage(true);
      const timer = setTimeout(() => setShowOnlineMessage(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [isOnline, showWhenOnline]);

  const handleRetry = async () => {
    setIsChecking(true);
    await checkConnection();
    setIsChecking(false);
  };

  const positionClasses = position === 'top' ? 'top-0 left-0 right-0' : 'bottom-0 left-0 right-0';

  // Don't render if online and not showing online message
  if (isOnline && !showOnlineMessage && !isSlowConnection) {
    return null;
  }

  return (
    <AnimatePresence>
      <motion.div
        initial={{ y: position === 'top' ? -100 : 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: position === 'top' ? -100 : 100, opacity: 0 }}
        className={`fixed ${positionClasses} z-[300] p-4 pointer-events-none`}
      >
        <div
          className={`
                    max-w-md mx-auto pointer-events-auto
                    ${
                      isOnline && showOnlineMessage
                        ? 'bg-green-500'
                        : isSlowConnection
                          ? 'bg-amber-500'
                          : 'bg-red-500'
                    }
                    text-white rounded-2xl
                    flex items-center gap-3 px-4 py-3
                `}
        >
          {isOnline && showOnlineMessage ? (
            <>
              <Wifi className="w-5 h-5" />
              <span className="flex-1 font-medium">Back online!</span>
            </>
          ) : isSlowConnection ? (
            <>
              <AlertTriangle className="w-5 h-5" />
              <span className="flex-1 font-medium">Slow connection detected</span>
            </>
          ) : (
            <>
              <WifiOff className="w-5 h-5" />
              <div className="flex-1">
                <p className="font-medium">You're offline</p>
                <p className="text-sm text-white/80">Some features may not be available</p>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={handleRetry}
                disabled={isChecking}
                title="Retry connection"
                className="bg-white/20 hover:bg-white/30"
              >
                <RefreshCw className={`w-5 h-5 ${isChecking ? 'animate-spin' : ''}`} />
              </Button>
            </>
          )}
        </div>
      </motion.div>
    </AnimatePresence>
  );
};

// Queue for offline actions
interface OfflineAction {
  id: string;
  type: string;
  payload: any;
  timestamp: number;
  retries: number;
}

const OFFLINE_QUEUE_KEY = 'genesis_offline_queue';

export function useOfflineQueue() {
  const [queue, setQueue] = useState<OfflineAction[]>(() => {
    try {
      const stored = localStorage.getItem(OFFLINE_QUEUE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch {
      return [];
    }
  });

  const { isOnline } = useNetworkStatus();

  // Save queue to localStorage
  useEffect(() => {
    localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(queue));
  }, [queue]);

  // Add action to queue
  const addToQueue = useCallback((type: string, payload: any) => {
    const action: OfflineAction = {
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      payload,
      timestamp: Date.now(),
      retries: 0,
    };
    setQueue((prev) => [...prev, action]);
    return action.id;
  }, []);

  // Remove action from queue
  const removeFromQueue = useCallback((id: string) => {
    setQueue((prev) => prev.filter((action) => action.id !== id));
  }, []);

  // Process queue when back online
  const processQueue = useCallback(
    async (processor: (action: OfflineAction) => Promise<boolean>) => {
      if (!isOnline || queue.length === 0) return;

      for (const action of queue) {
        try {
          const success = await processor(action);
          if (success) {
            removeFromQueue(action.id);
          } else {
            // Increment retry count
            setQueue((prev) =>
              prev.map((a) => (a.id === action.id ? { ...a, retries: a.retries + 1 } : a))
            );
          }
        } catch (error) {
          console.error('[OfflineQueue] Failed to process action:', action, error);
        }
      }
    },
    [isOnline, queue, removeFromQueue]
  );

  // Clear old actions (older than 24 hours)
  useEffect(() => {
    const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
    setQueue((prev) => prev.filter((action) => action.timestamp > oneDayAgo));
  }, []);

  return {
    queue,
    queueLength: queue.length,
    addToQueue,
    removeFromQueue,
    processQueue,
    clearQueue: () => setQueue([]),
  };
}

export default { useNetworkStatus, OfflineIndicator, useOfflineQueue };

import { type TouchEvent, useCallback, useRef, useState } from 'react';

export type SwipeDirection = 'left' | 'right' | 'up' | 'down';

interface SwipeConfig {
  threshold?: number; // minimum distance to trigger swipe
  velocity?: number; // minimum velocity to trigger swipe
  onSwipeLeft?: () => void;
  onSwipeRight?: () => void;
  onSwipeUp?: () => void;
  onSwipeDown?: () => void;
  onSwipe?: (direction: SwipeDirection) => void;
  preventDefaultOnSwipe?: boolean;
}

interface SwipeState {
  swiping: boolean;
  direction: SwipeDirection | null;
  offset: { x: number; y: number };
  velocity: { x: number; y: number };
}

interface TouchPoint {
  x: number;
  y: number;
  time: number;
}

export function useSwipeGesture(config: SwipeConfig = {}) {
  const {
    threshold = 50,
    velocity: velocityThreshold = 0.3,
    onSwipeLeft,
    onSwipeRight,
    onSwipeUp,
    onSwipeDown,
    onSwipe,
    preventDefaultOnSwipe = false,
  } = config;

  const [state, setState] = useState<SwipeState>({
    swiping: false,
    direction: null,
    offset: { x: 0, y: 0 },
    velocity: { x: 0, y: 0 },
  });

  const startRef = useRef<TouchPoint | null>(null);
  const currentRef = useRef<TouchPoint | null>(null);

  const handleTouchStart = useCallback((e: TouchEvent) => {
    const touch = e.touches[0];
    startRef.current = {
      x: touch.clientX,
      y: touch.clientY,
      time: Date.now(),
    };
    currentRef.current = startRef.current;
    setState((prev) => ({ ...prev, swiping: true }));
  }, []);

  const handleTouchMove = useCallback(
    (e: TouchEvent) => {
      if (!startRef.current) return;

      const touch = e.touches[0];
      const now = Date.now();

      currentRef.current = {
        x: touch.clientX,
        y: touch.clientY,
        time: now,
      };

      const deltaX = currentRef.current.x - startRef.current.x;
      const deltaY = currentRef.current.y - startRef.current.y;
      const deltaTime = (now - startRef.current.time) / 1000;

      const velocityX = deltaX / deltaTime;
      const velocityY = deltaY / deltaTime;

      // Determine swipe direction
      let direction: SwipeDirection | null = null;
      if (Math.abs(deltaX) > Math.abs(deltaY)) {
        direction = deltaX > 0 ? 'right' : 'left';
      } else {
        direction = deltaY > 0 ? 'down' : 'up';
      }

      setState({
        swiping: true,
        direction,
        offset: { x: deltaX, y: deltaY },
        velocity: { x: velocityX, y: velocityY },
      });

      if (preventDefaultOnSwipe && Math.abs(deltaX) > 10) {
        e.preventDefault();
      }
    },
    [preventDefaultOnSwipe]
  );

  const handleTouchEnd = useCallback(() => {
    if (!startRef.current || !currentRef.current) {
      setState({
        swiping: false,
        direction: null,
        offset: { x: 0, y: 0 },
        velocity: { x: 0, y: 0 },
      });
      return;
    }

    const deltaX = currentRef.current.x - startRef.current.x;
    const deltaY = currentRef.current.y - startRef.current.y;
    const deltaTime = (currentRef.current.time - startRef.current.time) / 1000;

    const velocityX = Math.abs(deltaX / deltaTime);
    const velocityY = Math.abs(deltaY / deltaTime);

    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);

    let direction: SwipeDirection | null = null;

    // Check if swipe meets threshold (distance or velocity)
    if (absX > absY) {
      if (absX > threshold || velocityX > velocityThreshold * 1000) {
        direction = deltaX > 0 ? 'right' : 'left';
      }
    } else if (absY > threshold || velocityY > velocityThreshold * 1000) {
      direction = deltaY > 0 ? 'down' : 'up';
    }

    // Trigger callbacks
    if (direction) {
      onSwipe?.(direction);

      switch (direction) {
        case 'left':
          onSwipeLeft?.();
          break;
        case 'right':
          onSwipeRight?.();
          break;
        case 'up':
          onSwipeUp?.();
          break;
        case 'down':
          onSwipeDown?.();
          break;
      }
    }

    // Reset state
    startRef.current = null;
    currentRef.current = null;
    setState({ swiping: false, direction: null, offset: { x: 0, y: 0 }, velocity: { x: 0, y: 0 } });
  }, [threshold, velocityThreshold, onSwipe, onSwipeLeft, onSwipeRight, onSwipeUp, onSwipeDown]);

  const handlers = {
    onTouchStart: handleTouchStart,
    onTouchMove: handleTouchMove,
    onTouchEnd: handleTouchEnd,
    onTouchCancel: handleTouchEnd,
  };

  return { ...state, handlers };
}

import { AnimatePresence, type PanInfo, motion } from 'framer-motion';
// Swipeable Page Navigator Component
import type React from 'react';
import { Button } from '../components/ui/button';

interface SwipeablePageProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  children: React.ReactNode;
  className?: string;
}

export const SwipeablePage: React.FC<SwipeablePageProps> = ({
  currentPage,
  totalPages,
  onPageChange,
  children,
  className = '',
}) => {
  const handleDragEnd = (_event: any, info: PanInfo) => {
    const threshold = 100;
    const velocity = info.velocity.x;
    const offset = info.offset.x;

    if (offset < -threshold || velocity < -500) {
      // Swiped left - next page
      if (currentPage < totalPages - 1) {
        onPageChange(currentPage + 1);
      }
    } else if (offset > threshold || velocity > 500) {
      // Swiped right - previous page
      if (currentPage > 0) {
        onPageChange(currentPage - 1);
      }
    }
  };

  return (
    <motion.div
      className={`touch-pan-y ${className}`}
      drag="x"
      dragConstraints={{ left: 0, right: 0 }}
      dragElastic={0.2}
      onDragEnd={handleDragEnd}
      whileDrag={{ cursor: 'grabbing' }}
    >
      <AnimatePresence mode="wait">
        <motion.div
          key={currentPage}
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -50 }}
          transition={{ duration: 0.2 }}
        >
          {children}
        </motion.div>
      </AnimatePresence>
    </motion.div>
  );
};

