import { useCallback, useEffect, useRef, useState } from 'react';

interface HistoryState<T> {
  past: T[];
  present: T;
  future: T[];
}

interface UseUndoRedoOptions<T> {
  maxHistory?: number;
  onUndo?: (state: T) => void;
  onRedo?: (state: T) => void;
}

export function useUndoRedo<T>(initialState: T, options: UseUndoRedoOptions<T> = {}) {
  const { maxHistory = 50, onUndo, onRedo } = options;

  const [history, setHistory] = useState<HistoryState<T>>({
    past: [],
    present: initialState,
    future: [],
  });

  const canUndo = history.past.length > 0;
  const canRedo = history.future.length > 0;

  // Update state and push to history
  const set = useCallback(
    (newState: T | ((prev: T) => T)) => {
      setHistory((prev) => {
        const nextState =
          typeof newState === 'function' ? (newState as (prev: T) => T)(prev.present) : newState;

        // Don't add to history if state hasn't changed
        if (JSON.stringify(nextState) === JSON.stringify(prev.present)) {
          return prev;
        }

        const newPast = [...prev.past, prev.present].slice(-maxHistory);

        return {
          past: newPast,
          present: nextState,
          future: [], // Clear redo stack on new change
        };
      });
    },
    [maxHistory]
  );

  // Undo to previous state
  const undo = useCallback(() => {
    setHistory((prev) => {
      if (prev.past.length === 0) return prev;

      const previous = prev.past[prev.past.length - 1];
      const newPast = prev.past.slice(0, -1);

      onUndo?.(previous);

      return {
        past: newPast,
        present: previous,
        future: [prev.present, ...prev.future],
      };
    });
  }, [onUndo]);

  // Redo to next state
  const redo = useCallback(() => {
    setHistory((prev) => {
      if (prev.future.length === 0) return prev;

      const next = prev.future[0];
      const newFuture = prev.future.slice(1);

      onRedo?.(next);

      return {
        past: [...prev.past, prev.present],
        present: next,
        future: newFuture,
      };
    });
  }, [onRedo]);

  // Reset history
  const reset = useCallback((newState: T) => {
    setHistory({
      past: [],
      present: newState,
      future: [],
    });
  }, []);

  // Clear history but keep current state
  const clearHistory = useCallback(() => {
    setHistory((prev) => ({
      past: [],
      present: prev.present,
      future: [],
    }));
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'z') {
        if (e.shiftKey) {
          e.preventDefault();
          redo();
        } else {
          e.preventDefault();
          undo();
        }
      }
      if ((e.metaKey || e.ctrlKey) && e.key === 'y') {
        e.preventDefault();
        redo();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  return {
    state: history.present,
    set,
    undo,
    redo,
    reset,
    clearHistory,
    canUndo,
    canRedo,
    historyLength: history.past.length,
    futureLength: history.future.length,
  };
}

// Hook for auto-saving
interface UseAutoSaveOptions<T> {
  data: T;
  onSave: (data: T) => Promise<void> | void;
  interval?: number; // milliseconds
  enabled?: boolean;
  debounceDelay?: number;
}

export function useAutoSave<T>({
  data,
  onSave,
  interval = 30000, // 30 seconds default
  enabled = true,
  debounceDelay = 2000,
}: UseAutoSaveOptions<T>) {
  const [isSaving, setIsSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [error, setError] = useState<string | null>(null);
  const lastDataRef = useRef<string>(JSON.stringify(data));
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);

  // Save function
  const save = useCallback(
    async (force = false) => {
      const currentData = JSON.stringify(data);

      // Skip if data hasn't changed (unless forced)
      if (!force && currentData === lastDataRef.current) {
        return;
      }

      setIsSaving(true);
      setError(null);

      try {
        await onSave(data);
        lastDataRef.current = currentData;
        setLastSaved(new Date());
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to save');
        console.error('[AutoSave] Error:', err);
      } finally {
        setIsSaving(false);
      }
    },
    [data, onSave]
  );

  // Debounced save on data change
  useEffect(() => {
    if (!enabled) return;

    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      save();
    }, debounceDelay);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [data, enabled, debounceDelay, save]);

  // Periodic save
  useEffect(() => {
    if (!enabled || interval <= 0) return;

    intervalRef.current = setInterval(() => {
      save();
    }, interval);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enabled, interval, save]);

  // Save on unmount
  useEffect(() => {
    return () => {
      if (enabled) {
        save(true);
      }
    };
  }, []);

  // Keyboard shortcut for manual save
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault();
        save(true);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [save]);

  return {
    isSaving,
    lastSaved,
    error,
    save: () => save(true),
  };
}

import { Check, Cloud, CloudOff, Loader2 } from 'lucide-react';
// Auto-save indicator component
import type React from 'react';

interface AutoSaveIndicatorProps {
  isSaving: boolean;
  lastSaved: Date | null;
  error: string | null;
}

export const AutoSaveIndicator: React.FC<AutoSaveIndicatorProps> = ({
  isSaving,
  lastSaved,
  error,
}) => {
  const formatTime = (date: Date) => {
    const now = new Date();
    const diff = now.getTime() - date.getTime();

    if (diff < 60000) return 'Just now';
    if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  if (error) {
    return (
      <div className="flex items-center gap-2 text-red-500 text-sm">
        <CloudOff className="w-4 h-4" />
        <span>Failed to save</span>
      </div>
    );
  }

  if (isSaving) {
    return (
      <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
        <Loader2 className="w-4 h-4 animate-spin" />
        <span>Saving...</span>
      </div>
    );
  }

  if (lastSaved) {
    return (
      <div className="flex items-center gap-2 text-green-600 dark:text-green-400 text-sm">
        <Check className="w-4 h-4" />
        <span>Saved {formatTime(lastSaved)}</span>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2 text-gray-400 text-sm">
      <Cloud className="w-4 h-4" />
      <span>Auto-save enabled</span>
    </div>
  );
};

export default { useUndoRedo, useAutoSave, AutoSaveIndicator };

import type React from 'react';
import { type ReactNode, createContext, useEffect, useState } from 'react';
import { fontPairings } from '../config/fontPairings';
import { useDynamicFontLoader } from '../hooks/useDynamicFontLoader';
import type { FontPairing } from '../types/fonts';

interface FontContextType {
  activeFontPairing: FontPairing;
  setFontPairing: (pairingId: string) => void;
  availablePairings: FontPairing[];
  isLoading: boolean;
}

export const FontContext = createContext<FontContextType | undefined>(undefined);

// Default fallback font pairing in case import fails
const DEFAULT_FONT_PAIRING: FontPairing = {
  id: 'default',
  name: 'Default',
  description: 'System default fonts',
  category: 'playful',
  headingFont: { family: 'system-ui', weights: [400, 700], fallback: 'sans-serif' },
  bodyFont: { family: 'system-ui', weights: [400, 700], fallback: 'sans-serif' },
  preview: { headingText: 'Preview', bodyText: 'Preview text' },
  bestFor: ['General'],
};

export const FontProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Initialize from localStorage or default with defensive fallback
  const [activeFontPairing, setActiveFontPairingState] = useState<FontPairing>(() => {
    try {
      if (!fontPairings || fontPairings.length === 0) {
        console.warn('[FontContext] No font pairings available, using default');
        return DEFAULT_FONT_PAIRING;
      }
      const savedId = localStorage.getItem('genesis_font_pairing');
      return fontPairings.find((p) => p.id === savedId) || fontPairings[0] || DEFAULT_FONT_PAIRING;
    } catch (error) {
      console.error('[FontContext] Error initializing font pairing:', error);
      return DEFAULT_FONT_PAIRING;
    }
  });

  // Use the dynamic loader hook
  const { isLoading } = useDynamicFontLoader(activeFontPairing);

  const setFontPairing = (pairingId: string) => {
    const pairing = fontPairings.find((p) => p.id === pairingId);
    if (pairing) {
      setActiveFontPairingState(pairing);
      localStorage.setItem('genesis_font_pairing', pairingId);
    }
  };

  // Apply CSS variables whenever the active font changes
  useEffect(() => {
    const root = document.documentElement;

    // Set font families
    root.style.setProperty(
      '--font-heading',
      `'${activeFontPairing.headingFont.family}', ${activeFontPairing.headingFont.fallback}`
    );
    root.style.setProperty(
      '--font-body',
      `'${activeFontPairing.bodyFont.family}', ${activeFontPairing.bodyFont.fallback}`
    );

    // Optional: Set font weights if needed for specific overrides,
    // but usually handled by utility classes
  }, [activeFontPairing]);

  return (
    <FontContext.Provider
      value={{
        activeFontPairing,
        setFontPairing,
        availablePairings: fontPairings,
        isLoading,
      }}
    >
      {children}
    </FontContext.Provider>
  );
};

/**
 * Language Context for Genesis
 *
 * Provides language management, RTL support, and formatting utilities
 * throughout the application.
 */

import type React from 'react';
import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import {
  FALLBACK_LANGUAGE,
  LANGUAGE_STORAGE_KEY,
  SUPPORTED_LANGUAGES,
  getDefaultLanguage,
  getLanguageByCode,
  isValidLanguageCode,
} from '../config/languages';
import type { Language, LanguageCode, LanguageContextType } from '../types/language.d';

// Create the context
const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

interface LanguageProviderProps {
  children: React.ReactNode;
}

export const LanguageProvider: React.FC<LanguageProviderProps> = ({ children }) => {
  const { i18n } = useTranslation();
  const [isLoading, setIsLoading] = useState(false);
  const [currentLanguage, setCurrentLanguage] = useState<Language>(getDefaultLanguage());

  // Initialize language from i18n
  useEffect(() => {
    const currentCode = i18n.language as LanguageCode;
    if (isValidLanguageCode(currentCode)) {
      const lang = getLanguageByCode(currentCode);
      if (lang) {
        setCurrentLanguage(lang);
        applyLanguageToDocument(lang);
      }
    }
  }, [i18n.language]);

  // Listen for language changes from i18n
  useEffect(() => {
    const handleLanguageChange = (lng: string) => {
      if (isValidLanguageCode(lng)) {
        const lang = getLanguageByCode(lng as LanguageCode);
        if (lang) {
          setCurrentLanguage(lang);
          applyLanguageToDocument(lang);
        }
      }
    };

    i18n.on('languageChanged', handleLanguageChange);
    return () => {
      i18n.off('languageChanged', handleLanguageChange);
    };
  }, [i18n]);

  /**
   * Apply language settings to the document (RTL, lang attribute)
   */
  const applyLanguageToDocument = useCallback((language: Language) => {
    const html = document.documentElement;
    const body = document.body;

    // Set lang attribute
    html.setAttribute('lang', language.code);

    // Set direction attribute
    html.setAttribute('dir', language.direction);

    // Add RTL class for Tailwind utilities
    if (language.isRTL) {
      html.classList.add('rtl');
      html.classList.remove('ltr');
    } else {
      html.classList.add('ltr');
      html.classList.remove('rtl');
    }

    // Add language class to body for conditional styling
    body.className = body.className.replace(/lang-\w+/g, '');
    body.classList.add(`lang-${language.code}`);

    // Store preference
    localStorage.setItem(LANGUAGE_STORAGE_KEY, language.code);

    // Dispatch custom event to notify other components
    window.dispatchEvent(new CustomEvent('languageChanged', { detail: { language } }));
  }, []);

  /**
   * Change the current language
   */
  const changeLanguage = useCallback(
    async (code: LanguageCode): Promise<void> => {
      if (!isValidLanguageCode(code)) {
        console.error(`[LanguageContext] Invalid language code: ${code}`);
        return;
      }

      const targetLanguage = getLanguageByCode(code);
      if (!targetLanguage) {
        console.error(`[LanguageContext] Language not found: ${code}`);
        return;
      }

      setIsLoading(true);

      try {
        // Change i18n language (this loads the translation files)
        await i18n.changeLanguage(code);

        // Update state
        setCurrentLanguage(targetLanguage);

        // Apply to document
        applyLanguageToDocument(targetLanguage);

        console.log(`[LanguageContext] Language changed to: ${targetLanguage.name}`);
      } catch (error) {
        console.error(`[LanguageContext] Failed to change language:`, error);
        // Fallback to English
        await i18n.changeLanguage(FALLBACK_LANGUAGE);
      } finally {
        setIsLoading(false);
      }
    },
    [i18n, applyLanguageToDocument]
  );

  /**
   * Format a date according to current locale
   */
  const formatDate = useCallback(
    (date: Date | string | number): string => {
      const dateObj = date instanceof Date ? date : new Date(date);
      try {
        return new Intl.DateTimeFormat(currentLanguage.numberFormat, {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        }).format(dateObj);
      } catch {
        return dateObj.toLocaleDateString();
      }
    },
    [currentLanguage.numberFormat]
  );

  /**
   * Format a number according to current locale
   */
  const formatNumber = useCallback(
    (num: number): string => {
      try {
        return new Intl.NumberFormat(currentLanguage.numberFormat).format(num);
      } catch {
        return num.toLocaleString();
      }
    },
    [currentLanguage.numberFormat]
  );

  /**
   * Format currency according to current locale
   */
  const formatCurrency = useCallback(
    (amount: number, currencyCode?: string): string => {
      const currency = currencyCode || currentLanguage.currency;
      try {
        return new Intl.NumberFormat(currentLanguage.numberFormat, {
          style: 'currency',
          currency,
        }).format(amount);
      } catch {
        return `${currency} ${amount.toFixed(2)}`;
      }
    },
    [currentLanguage.numberFormat, currentLanguage.currency]
  );

  /**
   * Format relative time (e.g., "2 hours ago")
   */
  const formatRelativeTime = useCallback(
    (date: Date | string | number): string => {
      const dateObj = date instanceof Date ? date : new Date(date);
      const now = new Date();
      const diffInSeconds = Math.floor((now.getTime() - dateObj.getTime()) / 1000);

      try {
        const rtf = new Intl.RelativeTimeFormat(currentLanguage.numberFormat, { numeric: 'auto' });

        if (diffInSeconds < 60) {
          return rtf.format(-diffInSeconds, 'second');
        } else if (diffInSeconds < 3600) {
          return rtf.format(-Math.floor(diffInSeconds / 60), 'minute');
        } else if (diffInSeconds < 86400) {
          return rtf.format(-Math.floor(diffInSeconds / 3600), 'hour');
        } else if (diffInSeconds < 2592000) {
          return rtf.format(-Math.floor(diffInSeconds / 86400), 'day');
        } else if (diffInSeconds < 31536000) {
          return rtf.format(-Math.floor(diffInSeconds / 2592000), 'month');
        } else {
          return rtf.format(-Math.floor(diffInSeconds / 31536000), 'year');
        }
      } catch {
        return dateObj.toLocaleDateString();
      }
    },
    [currentLanguage.numberFormat]
  );

  // Memoize context value
  const contextValue = useMemo<LanguageContextType>(
    () => ({
      currentLanguage,
      languages: SUPPORTED_LANGUAGES,
      changeLanguage,
      direction: currentLanguage.direction,
      isLoading,
      formatDate,
      formatNumber,
      formatCurrency,
      formatRelativeTime,
    }),
    [
      currentLanguage,
      changeLanguage,
      isLoading,
      formatDate,
      formatNumber,
      formatCurrency,
      formatRelativeTime,
    ]
  );

  return <LanguageContext.Provider value={contextValue}>{children}</LanguageContext.Provider>;
};

/**
 * Hook to access language context
 */
export const useLanguageContext = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguageContext must be used within a LanguageProvider');
  }
  return context;
};

export default LanguageContext;

/// <reference types="vitest/globals" />
import { type RenderOptions, render } from '@testing-library/react';
import type { ReactElement, ReactNode } from 'react';

/**
 * Custom render function that wraps components with providers
 * Add your app providers here (Theme, Auth, i18n, etc.)
 */
interface CustomRenderOptions extends Omit<RenderOptions, 'wrapper'> {
  initialState?: Record<string, unknown>;
}

const AllProviders = ({ children }: { children: ReactNode }) => {
  // Add your providers here, e.g.:
  // <ThemeProvider>
  //   <AuthProvider>
  //     <I18nProvider>
  //       {children}
  //     </I18nProvider>
  //   </AuthProvider>
  // </ThemeProvider>
  return <>{children}</>;
};

const customRender = (
  ui: ReactElement,
  options?: CustomRenderOptions
): ReturnType<typeof render> => {
  return render(ui, { wrapper: AllProviders, ...options });
};

export * from '@testing-library/react';
export { customRender as render };

/**
 * Wait for async operations to complete
 */
export const waitForAsync = (ms = 0): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Create a mock function with proper typing
 */
export const createMockFn = <T extends (...args: unknown[]) => unknown>(implementation?: T) =>
